-- PinoyQuiz -- consolidated schema + seed script
-- Generated for fresh Supabase project: ceopcnbcftlradoplgmy
-- Run this ONCE in the SQL Editor of the new project (or via CLI).
-- Combines supabase/migrations/0001-0035 + supabase/seed/0001-0004 in order.


-- ===================================================================
-- FROM: supabase/migrations/0001_extensions.sql
-- ===================================================================
-- Pinoy Quiz — 0001: extensions
-- gen_random_uuid() is built into Postgres core (13+), which Supabase runs,
-- but pgcrypto is enabled too since Supabase projects ship with it by default
-- and some environments still expect it explicitly.
create extension if not exists pgcrypto;


-- ===================================================================
-- FROM: supabase/migrations/0002_enums.sql
-- ===================================================================
-- Pinoy Quiz — 0002: enum types

-- Game state machine (see docs/ARCHITECTURE.md).
-- Clients render off this value; only server-side functions ever write it.
create type game_status as enum (
  'WAITING',
  'COUNTDOWN',
  'QUESTION',
  'REVEAL',
  'LEADERBOARD',
  'FINISHED'
);

-- 'random' is a valid *game setting* (meaning "any category"), but is never
-- stored on an individual question row — enforced by two separate types.
create type game_category_setting as enum (
  'history',
  'geography',
  'culture',
  'food',
  'entertainment',
  'sports',
  'trivia',
  'slang',
  'random'
);

create type question_category as enum (
  'history',
  'geography',
  'culture',
  'food',
  'entertainment',
  'sports',
  'trivia',
  'slang'
);

create type question_difficulty as enum ('easy', 'medium', 'hard');

-- A game setting can additionally accept "mixed" difficulty (any of the three).
create type game_difficulty_setting as enum ('easy', 'medium', 'hard', 'mixed');

create type answer_option as enum ('A', 'B', 'C', 'D');


-- ===================================================================
-- FROM: supabase/migrations/0003_tables.sql
-- ===================================================================
-- Pinoy Quiz — 0003: core tables
-- FKs to auth.users assume Supabase Auth (anonymous sign-in — see
-- docs/ARCHITECTURE.md "Security model"). Every player, including the host,
-- authenticates anonymously via supabase.auth.signInAnonymously() before
-- joining/creating a room, so auth.uid() is always available for RLS.

create table if not exists games (
  id                    uuid primary key default gen_random_uuid(),
  room_code             text not null,
  host_user_id          uuid not null references auth.users(id) on delete cascade,
  status                game_status not null default 'WAITING',

  -- settings, editable by host only while status = 'WAITING'
  category              game_category_setting not null default 'random',
  difficulty            game_difficulty_setting not null default 'mixed',
  question_count        smallint not null default 10,
  time_limit_seconds    smallint not null default 15,

  -- scoring is configurable per game, not hard-coded in application logic
  scoring_config        jsonb not null default jsonb_build_object(
                           'basePoints', 1000,
                           'maxSpeedBonus', 500,
                           'incorrectPoints', 0,
                           'noAnswerPoints', 0
                         ),

  -- live play state — written only by server-side functions (Phase 5/6)
  current_question_index smallint not null default 0,
  current_question_id    uuid, -- FK added after game_questions exists
  question_started_at    timestamptz, -- server-authoritative timer anchor

  created_at            timestamptz not null default now(),
  started_at            timestamptz,
  finished_at           timestamptz,

  constraint games_room_code_format check (room_code ~ '^[A-Z0-9]{6}$'),
  constraint games_question_count_range check (question_count between 1 and 50),
  constraint games_time_limit_range check (time_limit_seconds between 5 and 120),
  constraint games_current_question_index_nonneg check (current_question_index >= 0)
);

-- Room codes must be unique only while "in use" — old finished games could in
-- principle reuse a code, but simplest correct rule for v1 is global
-- uniqueness. Revisit if room codes need to be recycled at scale.
create unique index if not exists games_room_code_key on games (room_code);
create index if not exists games_status_idx on games (status);
create index if not exists games_host_user_id_idx on games (host_user_id);

comment on column games.current_question_id is
  'References game_questions.id (added as FK in 0004) once a question is live. Null in WAITING/COUNTDOWN/FINISHED.';


create table if not exists players (
  id            uuid primary key default gen_random_uuid(),
  game_id       uuid not null references games(id) on delete cascade,
  user_id       uuid not null references auth.users(id) on delete cascade,
  nickname      text not null,
  score         integer not null default 0,
  is_host       boolean not null default false,
  connected     boolean not null default true,
  joined_at     timestamptz not null default now(),
  last_seen_at  timestamptz not null default now(),

  constraint players_nickname_length check (char_length(trim(nickname)) between 1 and 20),
  -- one player identity per (user, game) — re-joining the same room reuses the row
  constraint players_game_user_unique unique (game_id, user_id)
);

-- Case-insensitive unique nickname per room (spec 6.4 "duplicate nickname" error)
create unique index if not exists players_game_nickname_ci_key
  on players (game_id, lower(nickname));
create index if not exists players_game_id_idx on players (game_id);


create table if not exists questions (
  id              uuid primary key default gen_random_uuid(),
  category        question_category not null,
  difficulty      question_difficulty not null,
  prompt          text not null,
  option_a        text not null,
  option_b        text not null,
  option_c        text not null,
  option_d        text not null,
  correct_option  answer_option not null,
  explanation     text,
  created_at      timestamptz not null default now(),

  constraint questions_prompt_not_blank check (char_length(trim(prompt)) > 0)
);

create index if not exists questions_category_difficulty_idx
  on questions (category, difficulty);


create table if not exists game_questions (
  id              uuid primary key default gen_random_uuid(),
  game_id         uuid not null references games(id) on delete cascade,
  question_id     uuid not null references questions(id),
  question_order  smallint not null,

  -- Per-game answer shuffle. Maps *displayed* position (0-3) to the
  -- question's original option index (0=A .. 3=D), e.g. [2,0,3,1] means
  -- displayed slot 0 shows original option C. Computed once when the game
  -- is built (Phase 5) and never exposed to clients as "here's the mapping
  -- and here's which one is right" — only used server-side to check answers
  -- and to render option *text* in shuffled order.
  shuffle_map     smallint[] not null,

  constraint game_questions_order_unique unique (game_id, question_order),
  constraint game_questions_no_dupes unique (game_id, question_id),
  constraint game_questions_shuffle_map_shape check (array_length(shuffle_map, 1) = 4)
);

create index if not exists game_questions_game_id_idx on game_questions (game_id);

alter table games
  add constraint games_current_question_fk
  foreign key (current_question_id) references game_questions(id);


create table if not exists answers (
  id                uuid primary key default gen_random_uuid(),
  game_id           uuid not null references games(id) on delete cascade,
  player_id         uuid not null references players(id) on delete cascade,
  question_id       uuid not null references questions(id),
  selected_option   smallint, -- displayed position 0-3; null = no answer submitted
  is_correct        boolean not null default false,
  response_time_ms  integer,
  points            integer not null default 0,
  created_at        timestamptz not null default now(),

  constraint answers_selected_option_range check (selected_option between 0 and 3),
  -- exactly one submission per player per question — the DB itself enforces
  -- "no double submission", not just application logic
  constraint answers_one_per_player_per_question unique (game_id, player_id, question_id)
);

create index if not exists answers_game_question_idx on answers (game_id, question_id);
create index if not exists answers_player_idx on answers (player_id);


-- ===================================================================
-- FROM: supabase/migrations/0004_views.sql
-- ===================================================================
-- Pinoy Quiz — 0004: client-safe views
-- These exist so we can revoke direct table access to `questions` and still
-- let clients read what they're allowed to. See 0006_rls.sql / 0007_grants.sql.

-- No correct_option, no explanation. This is the only way the question bank
-- is ever visible to a browser.
create or replace view questions_public as
select
  id,
  category,
  difficulty,
  prompt,
  option_a,
  option_b,
  option_c,
  option_d
from questions;

-- Safe, ranked view of a game's players. Used for the lobby list and the
-- leaderboard — never exposes user_id or any auth-related identifier.
create or replace view leaderboard as
select
  p.id as player_id,
  p.game_id,
  p.nickname,
  p.score,
  p.is_host,
  p.connected,
  rank() over (partition by p.game_id order by p.score desc, p.joined_at asc) as rank
from players p;


-- ===================================================================
-- FROM: supabase/migrations/0005_rls.sql
-- ===================================================================
-- Pinoy Quiz — 0005: Row Level Security
--
-- Design (see docs/ARCHITECTURE.md "Security model"):
-- Every player — host included — signs in via Supabase Anonymous Auth
-- (supabase.auth.signInAnonymously()) before touching any table, so
-- auth.uid() is always available.
--
-- RLS here only ever grants SELECT. No INSERT/UPDATE/DELETE policy exists
-- for `anon`/`authenticated` on any table in this migration, and 0006
-- explicitly revokes those table privileges too. That's deliberate: every
-- write (create game, join, start, submit answer, advance state...) must go
-- through a SECURITY DEFINER Postgres function (Phase 3+), which runs as the
-- table owner and bypasses RLS. This is what makes "the server stays
-- authoritative" true on a client-only Supabase stack — the functions *are*
-- the server, and the client literally cannot reach the tables any other way.

alter table games enable row level security;
alter table players enable row level security;
alter table questions enable row level security;
alter table game_questions enable row level security;
alter table answers enable row level security;

-- Helper: "is the current user a player in this game?"
--
-- This MUST be its own SECURITY DEFINER function rather than an inline
-- `exists (select 1 from players where ...)` inside the players policy
-- itself. A policy on `players` that queries `players` (even via a self-join
-- alias) makes Postgres re-evaluate the same RLS policy recursively and it
-- errors out with "infinite recursion detected in policy for relation
-- players" — caught while validating these migrations locally. Running the
-- membership check inside a SECURITY DEFINER function makes that inner
-- query execute as the function owner, which bypasses RLS entirely, so
-- there's no recursive policy evaluation.
create or replace function is_game_participant(target_game_id uuid)
returns boolean
language sql
security definer
stable
set search_path = public
as $$
  select exists (
    select 1 from players
    where game_id = target_game_id and user_id = auth.uid()
  );
$$;

-- games: visible to the host, and to anyone who has already joined as a
-- player. A not-yet-joined client looking up a room code does NOT use this
-- policy — that lookup goes through a narrow SECURITY DEFINER function
-- (Phase 3) that returns only {exists, status, room_code}, so someone
-- probing room codes can't harvest full game rows.
create policy games_select_participant on games
  for select
  to authenticated
  using (
    host_user_id = auth.uid()
    or is_game_participant(games.id)
  );

-- players: visible to fellow players in the same game (lobby roster,
-- leaderboard). Prefer selecting from the `leaderboard` view in app code —
-- this table policy exists mainly so that view can resolve correctly and
-- for any direct-table reads the client genuinely needs (e.g. "am I host").
create policy players_select_same_game on players
  for select
  to authenticated
  using (is_game_participant(players.game_id));

-- questions: NO select policy at all. Direct table access is revoked in
-- 0006 regardless; RLS is enabled here too as defense in depth. All reads
-- go through the `questions_public` view (no correct_option/explanation) or,
-- for in-game delivery, a Phase 5 function scoped to the player's current
-- question only (so future questions in the same game aren't fetchable
-- early either).

-- game_questions: NO select policy. This table is server-internal — it
-- carries `shuffle_map`, which is exactly the thing a cheating client would
-- want. Only SECURITY DEFINER functions ever read it.

-- answers: a player may see only their own submissions. Aggregate stats
-- ("63% of players answered correctly") are computed by a SECURITY DEFINER
-- function in Phase 6, not by exposing other players' raw answer rows.
create policy answers_select_own on answers
  for select
  to authenticated
  using (
    exists (
      select 1 from players p
      where p.id = answers.player_id and p.user_id = auth.uid()
    )
  );


-- ===================================================================
-- FROM: supabase/migrations/0006_grants.sql
-- ===================================================================
-- Pinoy Quiz — 0006: grants
-- Belt-and-suspenders alongside 0005's RLS: revoke table privileges outright
-- so even a misconfigured policy can't accidentally allow a write.
-- Supabase's anonymous auth issues the `authenticated` role (with an
-- `is_anonymous` JWT claim) — there is no unauthenticated `anon` access in
-- this app; every client signs in anonymously first.

revoke all on games, players, questions, game_questions, answers
  from anon, authenticated;

-- Tables: authenticated clients may only ever SELECT, and only the rows
-- their RLS policy allows. No table grants INSERT/UPDATE/DELETE to anon or
-- authenticated anywhere in this schema — all writes happen inside
-- SECURITY DEFINER functions (Phase 3+), which run as the function owner
-- and are therefore unaffected by these revokes.
grant select on games, players, answers to authenticated;

-- questions and game_questions get NO direct grant, not even SELECT — see
-- 0005 comments. Client access is only ever through the views below or a
-- future scoped function.
grant select on questions_public to authenticated;
grant select on leaderboard to authenticated;


-- ===================================================================
-- FROM: supabase/migrations/0007_room_functions.sql
-- ===================================================================
-- Pinoy Quiz — 0007: create/join room functions
--
-- These are the first of the "the functions are the server" writes promised
-- in 0005/0006 — every table write in this app happens through a function
-- like these, never through a direct client INSERT/UPDATE. All of them
-- assume the caller already has an anonymous Supabase Auth session (see
-- ensureAnonymousSession() in src/lib/supabase.ts), so auth.uid() is never
-- null in normal use — the null check below is defense in depth.

-- Internal helper — not granted to any client role. Excludes visually
-- ambiguous characters (0/O, 1/I/L) so a room code is easy to read aloud
-- or type on a phone keyboard.
create or replace function generate_room_code()
returns text
language plpgsql
as $$
declare
  charset text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
  result text := '';
  i int;
begin
  for i in 1..6 loop
    result := result || substr(charset, (floor(random() * length(charset)) + 1)::int, 1);
  end loop;
  return result;
end;
$$;


create or replace function create_game(
  p_category game_category_setting default 'random',
  p_difficulty game_difficulty_setting default 'mixed',
  p_question_count smallint default 10,
  p_time_limit_seconds smallint default 15,
  p_host_nickname text default 'Host'
)
returns table (
  out_game_id uuid,
  out_room_code text,
  out_player_id uuid
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_room_code text;
  v_game_id uuid;
  v_player_id uuid;
  v_nickname text := trim(p_host_nickname);
  v_attempt int := 0;
begin
  if v_uid is null then
    raise exception 'You must be signed in to create a game.' using errcode = '28000';
  end if;

  if char_length(v_nickname) < 1 or char_length(v_nickname) > 20 then
    raise exception 'Nickname must be between 1 and 20 characters.' using errcode = '22023';
  end if;

  loop
    v_attempt := v_attempt + 1;
    v_room_code := generate_room_code();
    begin
      insert into games (room_code, host_user_id, category, difficulty, question_count, time_limit_seconds)
      values (v_room_code, v_uid, p_category, p_difficulty, p_question_count, p_time_limit_seconds)
      returning id into v_game_id;
      exit;
    exception when unique_violation then
      if v_attempt >= 10 then
        raise exception 'Could not allocate a room code — please try again.' using errcode = '55000';
      end if;
    end;
  end loop;

  insert into players (game_id, user_id, nickname, is_host)
  values (v_game_id, v_uid, v_nickname, true)
  returning id into v_player_id;

  return query select v_game_id, v_room_code, v_player_id;
end;
$$;


-- Narrow, pre-join lookup. Deliberately does NOT return the full `games`
-- row (no host_user_id, no id even) — just enough for the join screen to
-- show a friendly "this room doesn't exist" / "this game already started"
-- message before the player commits to joining. See docs/ARCHITECTURE.md.
create or replace function lookup_game_by_room_code(p_room_code text)
returns table (
  found boolean,
  status game_status,
  category game_category_setting,
  difficulty game_difficulty_setting,
  question_count smallint,
  time_limit_seconds smallint
)
language plpgsql
security definer
stable
set search_path = public
as $$
declare
  v_game games%rowtype;
begin
  select * into v_game from games where room_code = upper(trim(p_room_code));
  if not found then
    return query select false, null::game_status, null::game_category_setting,
      null::game_difficulty_setting, null::smallint, null::smallint;
    return;
  end if;
  return query select true, v_game.status, v_game.category, v_game.difficulty,
    v_game.question_count, v_game.time_limit_seconds;
end;
$$;


create or replace function join_game(
  p_room_code text,
  p_nickname text
)
returns table (
  out_game_id uuid,
  out_player_id uuid,
  out_status game_status,
  out_is_host boolean,
  out_reconnected boolean
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
  v_existing players%rowtype;
  v_player_id uuid;
  v_nickname text := trim(p_nickname);
  v_player_count int;
  v_max_players constant int := 50;
begin
  if v_uid is null then
    raise exception 'You must be signed in to join a game.' using errcode = '28000';
  end if;

  if char_length(v_nickname) < 1 or char_length(v_nickname) > 20 then
    raise exception 'Nickname must be between 1 and 20 characters.' using errcode = '22023';
  end if;

  select * into v_game from games where room_code = upper(trim(p_room_code));
  if not found then
    raise exception 'That room code doesn''t exist.' using errcode = 'P0002';
  end if;

  -- Reconnect: this browser (same anonymous auth session) already has a
  -- player row in this game. Rejoining always succeeds regardless of game
  -- status — a full disconnect/reconnect UX lands in Phase 8, but the data
  -- path belongs here since it's the same "arrive at this room" action.
  select * into v_existing from players where game_id = v_game.id and user_id = v_uid;
  if found then
    update players
      set connected = true, last_seen_at = now()
      where id = v_existing.id
      returning id into v_player_id;
    return query select v_game.id, v_player_id, v_game.status, v_existing.is_host, true;
    return;
  end if;

  if v_game.status <> 'WAITING' then
    raise exception 'This game has already started.' using errcode = 'P0001';
  end if;

  if exists (
    select 1 from players where game_id = v_game.id and lower(nickname) = lower(v_nickname)
  ) then
    raise exception 'That nickname is already taken in this room.' using errcode = '23505';
  end if;

  select count(*) into v_player_count from players where game_id = v_game.id;
  if v_player_count >= v_max_players then
    raise exception 'This room is full.' using errcode = '53400';
  end if;

  insert into players (game_id, user_id, nickname, is_host)
  values (v_game.id, v_uid, v_nickname, false)
  returning id into v_player_id;

  return query select v_game.id, v_player_id, v_game.status, false, false;
end;
$$;


-- Lock these down explicitly rather than relying on Postgres's default
-- "EXECUTE granted to PUBLIC on new functions" behavior.
revoke execute on function generate_room_code() from public;
revoke execute on function create_game(game_category_setting, game_difficulty_setting, smallint, smallint, text) from public;
revoke execute on function lookup_game_by_room_code(text) from public;
revoke execute on function join_game(text, text) from public;

grant execute on function create_game(game_category_setting, game_difficulty_setting, smallint, smallint, text) to authenticated;
grant execute on function lookup_game_by_room_code(text) to authenticated;
grant execute on function join_game(text, text) to authenticated;


-- ===================================================================
-- FROM: supabase/migrations/0008_realtime.sql
-- ===================================================================
-- Pinoy Quiz — 0008: realtime
-- Supabase provisions a `supabase_realtime` publication in every project;
-- tables must be explicitly added to it before postgres_changes events are
-- broadcast for them. Realtime respects each table's existing RLS policies
-- (0005_rls.sql) automatically — a client only receives change events for
-- rows it's already allowed to SELECT, so no separate "realtime policy" is
-- needed.
--
-- Note: this statement assumes the `supabase_realtime` publication already
-- exists, which it always does on a real Supabase project. It will fail on
-- a vanilla local Postgres unless that publication is created first — see
-- docs/ARCHITECTURE.md "Real-time multiplayer architecture" for how this
-- was validated without a live Realtime service.

alter publication supabase_realtime add table games;
alter publication supabase_realtime add table players;


-- ===================================================================
-- FROM: supabase/migrations/0009_lobby_functions.sql
-- ===================================================================
-- Pinoy Quiz — 0009: lobby host controls
-- remove_player rounds out the Phase 4 lobby: the host can remove someone
-- before the game starts (spec section 5, "Remove a player"). Like every
-- other write in this app, it's SECURITY DEFINER and RLS-inaccessible any
-- other way.

create or replace function remove_player(p_player_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_target players%rowtype;
  v_game games%rowtype;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  select * into v_target from players where id = p_player_id;
  if not found then
    raise exception 'That player has already left the room.' using errcode = 'P0002';
  end if;

  select * into v_game from games where id = v_target.game_id;

  if v_game.host_user_id <> v_uid then
    raise exception 'Only the host can remove players.' using errcode = '42501';
  end if;

  if v_target.user_id = v_uid then
    raise exception 'You can''t remove yourself — end the game instead.' using errcode = '22023';
  end if;

  delete from players where id = p_player_id;
end;
$$;

revoke execute on function remove_player(uuid) from public;
grant execute on function remove_player(uuid) to authenticated;


-- ===================================================================
-- FROM: supabase/migrations/0010_game_engine.sql
-- ===================================================================
-- Pinoy Quiz — 0010: game engine (Phase 5)
--
-- Covers the state machine from WAITING through serving the first
-- question: WAITING -> COUNTDOWN -> QUESTION. Answer submission, scoring,
-- and the REVEAL/LEADERBOARD/next-question/FINISHED transitions are
-- Phase 6/7 — deliberately not built here, so the state machine stops
-- part-way through its full cycle for now.

-- start_game: host-only. Builds this game's randomized, de-duplicated
-- question set (respecting the category/difficulty settings chosen at
-- creation) and moves the room from WAITING to COUNTDOWN. Does NOT yet
-- reveal a question to anyone — see begin_first_question.
create or replace function start_game(p_game_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
  v_player_count int;
  v_category_filter text;
  v_difficulty_filter text;
  v_question_ids uuid[];
  v_qid uuid;
  v_order smallint := 0;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  select * into v_game from games where id = p_game_id;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  if v_game.host_user_id <> v_uid then
    raise exception 'Only the host can start the game.' using errcode = '42501';
  end if;

  if v_game.status <> 'WAITING' then
    raise exception 'This game has already started.' using errcode = 'P0001';
  end if;

  select count(*) into v_player_count from players where game_id = p_game_id;
  if v_player_count < 1 then
    raise exception 'You need at least one player to start.' using errcode = 'P0004';
  end if;

  -- 'random'/'mixed' settings mean "no filter on that column"
  v_category_filter := nullif(v_game.category::text, 'random');
  v_difficulty_filter := nullif(v_game.difficulty::text, 'mixed');

  select array_agg(id) into v_question_ids
  from (
    select id from questions
    where (v_category_filter is null or category::text = v_category_filter)
      and (v_difficulty_filter is null or difficulty::text = v_difficulty_filter)
    order by random()
    limit v_game.question_count
  ) sub;

  if v_question_ids is null or array_length(v_question_ids, 1) < v_game.question_count then
    raise exception 'Not enough questions available for these settings. Try Random category or Mixed difficulty.'
      using errcode = 'P0005';
  end if;

  foreach v_qid in array v_question_ids loop
    insert into game_questions (game_id, question_id, question_order, shuffle_map)
    values (
      p_game_id,
      v_qid,
      v_order,
      (select array(select x from unnest(array[0,1,2,3]::smallint[]) x order by random()))
    );
    v_order := v_order + 1;
  end loop;

  update games set status = 'COUNTDOWN', started_at = now() where id = p_game_id;
end;
$$;


-- begin_first_question: host-only. Flips COUNTDOWN -> QUESTION and anchors
-- the server-authoritative timer (question_started_at). The client plays
-- a purely cosmetic countdown animation, then the host's client calls
-- this. A later phase may automate this away from being host-triggered,
-- but restricting it to the host for now means an impatient non-host
-- client can't cut the countdown short for everyone else.
create or replace function begin_first_question(p_game_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
  v_gq_id uuid;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  select * into v_game from games where id = p_game_id;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  if v_game.host_user_id <> v_uid then
    raise exception 'Only the host can do that.' using errcode = '42501';
  end if;

  if v_game.status <> 'COUNTDOWN' then
    raise exception 'This game is not ready to begin.' using errcode = 'P0001';
  end if;

  select id into v_gq_id from game_questions
  where game_id = p_game_id and question_order = 0;

  if v_gq_id is null then
    raise exception 'No questions were prepared for this game.' using errcode = 'P0006';
  end if;

  update games
    set status = 'QUESTION',
        current_question_index = 0,
        current_question_id = v_gq_id,
        question_started_at = now()
    where id = p_game_id;
end;
$$;


-- get_current_question: any participant. Returns ONLY the currently-live
-- question, with its answer options already shuffled into this game's
-- per-question order (via game_questions.shuffle_map) and NO correct-answer
-- field — the anti-cheat boundary from Phase 2 carried through to live
-- play. Returns zero rows if the game isn't in QUESTION status, so a
-- client can't fetch ahead by guessing at question IDs.
create or replace function get_current_question(p_game_id uuid)
returns table (
  out_question_id uuid,
  out_prompt text,
  out_option_1 text,
  out_option_2 text,
  out_option_3 text,
  out_option_4 text,
  out_order smallint,
  out_total smallint,
  out_time_limit_seconds smallint,
  out_question_started_at timestamptz
)
language plpgsql
security definer
stable
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
  v_gq game_questions%rowtype;
  v_q questions%rowtype;
  v_opts text[];
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  select * into v_game from games where id = p_game_id;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  if not exists (select 1 from players where game_id = p_game_id and user_id = v_uid) then
    raise exception 'You are not part of this game.' using errcode = '42501';
  end if;

  if v_game.status <> 'QUESTION' or v_game.current_question_id is null then
    return; -- no rows — nothing to show right now
  end if;

  select * into v_gq from game_questions where id = v_game.current_question_id;
  select * into v_q from questions where id = v_gq.question_id;

  v_opts := array[v_q.option_a, v_q.option_b, v_q.option_c, v_q.option_d];

  return query select
    v_q.id,
    v_q.prompt,
    v_opts[v_gq.shuffle_map[1] + 1],
    v_opts[v_gq.shuffle_map[2] + 1],
    v_opts[v_gq.shuffle_map[3] + 1],
    v_opts[v_gq.shuffle_map[4] + 1],
    (v_gq.question_order + 1)::smallint,
    v_game.question_count,
    v_game.time_limit_seconds,
    v_game.question_started_at;
end;
$$;


revoke execute on function start_game(uuid) from public;
revoke execute on function begin_first_question(uuid) from public;
revoke execute on function get_current_question(uuid) from public;

grant execute on function start_game(uuid) to authenticated;
grant execute on function begin_first_question(uuid) to authenticated;
grant execute on function get_current_question(uuid) to authenticated;


-- ===================================================================
-- FROM: supabase/migrations/0011_answer_submission.sql
-- ===================================================================
-- Pinoy Quiz — 0011: answer submission and scoring (Phase 6)
--
-- Covers the rest of the state machine's live-play half: submitting an
-- answer, the configurable scoring formula (games.scoring_config), the
-- QUESTION -> REVEAL transition, and a scoped reveal read. Advancing from
-- REVEAL to LEADERBOARD, moving to the next question, and FINISHED are
-- Phase 7 — deliberately not built here.

-- submit_answer: any participant, once per question. Validates the game is
-- actually in QUESTION status and the caller hasn't already answered this
-- question (the DB's answers_one_per_player_per_question constraint is the
-- real backstop, but we check first for a friendly error instead of a raw
-- constraint violation). Correctness and timing are both computed
-- server-side: correctness by mapping the *displayed* option the player
-- picked back through this game's shuffle_map to the question's real
-- correct_option, and timing from now() minus the server-authoritative
-- games.question_started_at — never from a client-reported elapsed time.
create or replace function submit_answer(p_game_id uuid, p_selected_option smallint)
returns table (
  out_is_correct boolean,
  out_points integer
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
  v_player players%rowtype;
  v_gq game_questions%rowtype;
  v_q questions%rowtype;
  v_correct_index smallint; -- 0-3, original A-D index of the correct option
  v_correct_slot smallint;  -- 0-3, displayed slot (post-shuffle) that is correct
  v_is_correct boolean;
  v_response_ms integer;
  v_time_limit_ms integer;
  v_scoring jsonb;
  v_speed_ratio numeric;
  v_speed_bonus integer;
  v_points integer;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  if p_selected_option is null or p_selected_option not between 0 and 3 then
    raise exception 'That is not a valid answer option.' using errcode = '22023';
  end if;

  select * into v_game from games where id = p_game_id;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  select * into v_player from players
    where game_id = p_game_id and user_id = v_uid;
  if not found then
    raise exception 'You are not part of this game.' using errcode = '42501';
  end if;

  if v_game.status <> 'QUESTION' or v_game.current_question_id is null then
    raise exception 'This question is no longer accepting answers.' using errcode = 'P0007';
  end if;

  if exists (
    select 1 from answers
    where game_id = p_game_id
      and player_id = v_player.id
      and question_id = (select question_id from game_questions where id = v_game.current_question_id)
  ) then
    raise exception 'You already answered this question.' using errcode = 'P0008';
  end if;

  select * into v_gq from game_questions where id = v_game.current_question_id;
  select * into v_q from questions where id = v_gq.question_id;

  -- Original A/B/C/D index (0-3) of the correct option.
  v_correct_index := array_position(array['A','B','C','D'], v_q.correct_option::text) - 1;
  -- Which *displayed* slot (post-shuffle) currently shows that original index.
  v_correct_slot := array_position(v_gq.shuffle_map, v_correct_index) - 1;
  v_is_correct := (p_selected_option = v_correct_slot);

  v_time_limit_ms := v_game.time_limit_seconds * 1000;
  v_response_ms := greatest(
    0,
    least(
      v_time_limit_ms,
      extract(epoch from (now() - v_game.question_started_at)) * 1000
    )
  )::integer;

  v_scoring := v_game.scoring_config;

  if v_is_correct then
    v_speed_ratio := 1 - (v_response_ms::numeric / greatest(v_time_limit_ms, 1));
    v_speed_bonus := round(
      (v_scoring->>'maxSpeedBonus')::numeric * greatest(0, least(1, v_speed_ratio))
    )::integer;
    v_points := (v_scoring->>'basePoints')::integer + v_speed_bonus;
  else
    v_points := (v_scoring->>'incorrectPoints')::integer;
  end if;

  insert into answers (
    game_id, player_id, question_id, selected_option,
    is_correct, response_time_ms, points
  ) values (
    p_game_id, v_player.id, v_q.id, p_selected_option,
    v_is_correct, v_response_ms, v_points
  );

  update players set score = score + v_points where id = v_player.id;

  return query select v_is_correct, v_points;
end;
$$;


-- end_question: host-only. Called once the host's client-side timer runs
-- out (a purely display-driven trigger — the server doesn't otherwise
-- police the clock, matching the rest of this app's "host controls
-- pacing" pattern from Phase 5). Anyone who never submitted an answer for
-- the live question gets a zero-points "no answer" row inserted, using
-- noAnswerPoints from the same per-game scoring_config, so scoring stays
-- table-driven rather than a hard-coded constant. Then flips
-- QUESTION -> REVEAL.
create or replace function end_question(p_game_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
  v_gq game_questions%rowtype;
  v_no_answer_points integer;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  select * into v_game from games where id = p_game_id;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  if v_game.host_user_id <> v_uid then
    raise exception 'Only the host can do that.' using errcode = '42501';
  end if;

  if v_game.status <> 'QUESTION' or v_game.current_question_id is null then
    raise exception 'This game is not in the question phase.' using errcode = 'P0001';
  end if;

  select * into v_gq from game_questions where id = v_game.current_question_id;
  v_no_answer_points := (v_game.scoring_config->>'noAnswerPoints')::integer;

  insert into answers (game_id, player_id, question_id, selected_option, is_correct, response_time_ms, points)
  select p_game_id, p.id, v_gq.question_id, null, false, null, v_no_answer_points
  from players p
  where p.game_id = p_game_id
    and not exists (
      select 1 from answers a
      where a.game_id = p_game_id and a.player_id = p.id and a.question_id = v_gq.question_id
    );

  update games set status = 'REVEAL' where id = p_game_id;
end;
$$;


-- get_answer_reveal: any participant, only while the game is in REVEAL.
-- Returns the correct answer (in this game's displayed/shuffled slot, so
-- the client can highlight the same option it rendered during QUESTION),
-- an explanation if one exists, this player's own submission and points,
-- and the percentage of players in the game who answered correctly —
-- computed here server-side rather than by relaxing answers_select_own,
-- so one player still can never read another's individual answer row.
create or replace function get_answer_reveal(p_game_id uuid)
returns table (
  out_question_id uuid,
  out_correct_option smallint,
  out_correct_text text,
  out_explanation text,
  out_your_answer smallint,
  out_your_points integer,
  out_was_correct boolean,
  out_percent_correct numeric
)
language plpgsql
security definer
stable
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
  v_player players%rowtype;
  v_gq game_questions%rowtype;
  v_q questions%rowtype;
  v_opts text[];
  v_correct_index smallint;
  v_correct_slot smallint;
  v_answer answers%rowtype;
  v_total_players int;
  v_correct_count int;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  select * into v_game from games where id = p_game_id;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  select * into v_player from players
    where game_id = p_game_id and user_id = v_uid;
  if not found then
    raise exception 'You are not part of this game.' using errcode = '42501';
  end if;

  if v_game.status <> 'REVEAL' or v_game.current_question_id is null then
    return; -- no rows — nothing to reveal right now
  end if;

  select * into v_gq from game_questions where id = v_game.current_question_id;
  select * into v_q from questions where id = v_gq.question_id;
  v_opts := array[v_q.option_a, v_q.option_b, v_q.option_c, v_q.option_d];

  v_correct_index := array_position(array['A','B','C','D'], v_q.correct_option::text) - 1;
  v_correct_slot := array_position(v_gq.shuffle_map, v_correct_index) - 1;

  select * into v_answer from answers
    where game_id = p_game_id and player_id = v_player.id and question_id = v_q.id;

  select count(*) into v_total_players from players where game_id = p_game_id;
  select count(*) into v_correct_count from answers
    where game_id = p_game_id and question_id = v_q.id and is_correct;

  return query select
    v_q.id,
    v_correct_slot,
    v_opts[v_correct_index + 1],
    v_q.explanation,
    v_answer.selected_option,
    coalesce(v_answer.points, 0),
    coalesce(v_answer.is_correct, false),
    case when v_total_players > 0
      then round(100.0 * v_correct_count / v_total_players, 1)
      else 0
    end;
end;
$$;


revoke execute on function submit_answer(uuid, smallint) from public;
revoke execute on function end_question(uuid) from public;
revoke execute on function get_answer_reveal(uuid) from public;

grant execute on function submit_answer(uuid, smallint) to authenticated;
grant execute on function end_question(uuid) to authenticated;
grant execute on function get_answer_reveal(uuid) to authenticated;


-- ===================================================================
-- FROM: supabase/migrations/0012_leaderboard.sql
-- ===================================================================
-- Pinoy Quiz — 0012: leaderboard and game completion (Phase 7)
--
-- Closes the loop the state machine has been stopping short of since
-- Phase 5/6: REVEAL -> LEADERBOARD -> (next QUESTION | FINISHED). Three
-- new host-callable/participant-callable functions, following the exact
-- SECURITY DEFINER pattern used by every write/scoped-read so far.

-- get_leaderboard: any participant, any status. Ranked standings for the
-- whole game (same ranking the `leaderboard` view already computes:
-- score desc, joined_at asc), plus a per-player `score_delta` — the points
-- earned on the question that was just played. Delta has to come from a
-- SECURITY DEFINER function rather than a direct client query against
-- `answers`, because `answers_select_own` (0005_rls.sql) only lets a
-- player read their own submissions — exactly the same reason
-- `get_answer_reveal`'s percent_correct is computed server-side in
-- 0011_answer_submission.sql. The `leaderboard` view itself remains fine
-- for the ranked score/rank columns (it's already client-readable), but
-- since we need one function anyway for the delta, it returns everything
-- the LEADERBOARD screen needs in a single call.
--
-- Also used, unmodified, by the FINISHED/Results screen: at that point
-- `current_question_id` still points at the last game_questions row
-- played, so score_delta there reflects "how the final question went" —
-- harmless, since Results only displays final score/rank, not the delta.
create or replace function get_leaderboard(p_game_id uuid)
returns table (
  out_player_id uuid,
  out_nickname text,
  out_score integer,
  out_rank bigint,
  out_score_delta integer
)
language plpgsql
security definer
stable
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
  v_last_question_id uuid;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  select * into v_game from games where id = p_game_id;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  if not exists (select 1 from players where game_id = p_game_id and user_id = v_uid) then
    raise exception 'You are not part of this game.' using errcode = '42501';
  end if;

  if v_game.current_question_id is not null then
    select question_id into v_last_question_id
    from game_questions where id = v_game.current_question_id;
  end if;

  return query
    select
      p.id,
      p.nickname,
      p.score,
      rank() over (order by p.score desc, p.joined_at asc),
      coalesce(a.points, 0)
    from players p
    left join answers a
      on a.player_id = p.id
      and a.game_id = p_game_id
      and a.question_id = v_last_question_id
    where p.game_id = p_game_id
    order by rank() over (order by p.score desc, p.joined_at asc);
end;
$$;


-- advance_to_leaderboard: host-only. REVEAL -> LEADERBOARD. A pure status
-- flip — score_delta is computed on read (get_leaderboard above) from the
-- answers already recorded during REVEAL/end_question, so nothing else on
-- the row needs to change here.
create or replace function advance_to_leaderboard(p_game_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  select * into v_game from games where id = p_game_id;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  if v_game.host_user_id <> v_uid then
    raise exception 'Only the host can do that.' using errcode = '42501';
  end if;

  if v_game.status <> 'REVEAL' then
    raise exception 'This game is not in the reveal phase.' using errcode = 'P0001';
  end if;

  update games set status = 'LEADERBOARD' where id = p_game_id;
end;
$$;


-- advance_question: host-only. LEADERBOARD -> next QUESTION, mirroring
-- begin_first_question's pattern (0010_game_engine.sql) for anchoring the
-- server-authoritative timer. If the question just shown on the
-- leaderboard was the last one in the set, moves to FINISHED instead and
-- stamps finished_at — the only way a game ever reaches FINISHED.
create or replace function advance_question(p_game_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
  v_next_index smallint;
  v_next_gq_id uuid;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  select * into v_game from games where id = p_game_id;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  if v_game.host_user_id <> v_uid then
    raise exception 'Only the host can do that.' using errcode = '42501';
  end if;

  if v_game.status <> 'LEADERBOARD' then
    raise exception 'This game is not on the leaderboard screen.' using errcode = 'P0001';
  end if;

  v_next_index := v_game.current_question_index + 1;

  if v_next_index < v_game.question_count then
    select id into v_next_gq_id from game_questions
      where game_id = p_game_id and question_order = v_next_index;

    if v_next_gq_id is null then
      raise exception 'No questions were prepared for this game.' using errcode = 'P0006';
    end if;

    update games
      set status = 'QUESTION',
          current_question_index = v_next_index,
          current_question_id = v_next_gq_id,
          question_started_at = now()
      where id = p_game_id;
  else
    update games
      set status = 'FINISHED',
          finished_at = now()
      where id = p_game_id;
  end if;
end;
$$;


revoke execute on function get_leaderboard(uuid) from public;
revoke execute on function advance_to_leaderboard(uuid) from public;
revoke execute on function advance_question(uuid) from public;

grant execute on function get_leaderboard(uuid) to authenticated;
grant execute on function advance_to_leaderboard(uuid) to authenticated;
grant execute on function advance_question(uuid) to authenticated;


-- ===================================================================
-- FROM: supabase/migrations/0013_disconnect_reconnect.sql
-- ===================================================================
-- Pinoy Quiz — 0013: disconnect/reconnect handling (Phase 8)
--
-- Closes the gap called out at the end of Phase 7: every state-machine
-- transition so far (start_game, begin_first_question, end_question,
-- advance_to_leaderboard, advance_question) is host-only and
-- client-triggered, with no server-side fallback if the host's tab closes
-- mid-game. This migration adds three SECURITY DEFINER functions:
--
--   heartbeat(game_id)          — any participant, called periodically by
--                                  their own client to prove they're still
--                                  around.
--   mark_stale_players(game_id) — any participant, called periodically by
--                                  *any* client (not just the host's) to
--                                  flip connected=false for anyone who's
--                                  stopped heartbeating.
--   claim_host(game_id)         — any *other* participant, to take over as
--                                  host once the current host is stale.
--
-- Mechanism choice — heartbeat/staleness over Realtime Presence:
-- docs/ARCHITECTURE.md flags both as options ("Presence... is the natural
-- fit... The `connected` DB column... could instead become 'haven't ack'd
-- in N seconds' via a heartbeat"). Presence would give faster, more
-- immediate "who's got a live socket right now" signal, but — like the
-- rest of Supabase Realtime (see Phase 4's CHANGELOG entry and
-- useGameRealtime.ts's doc comment) — it's a hosted service this sandbox
-- cannot exercise at all, live-wire behavior included. A heartbeat is a
-- plain SECURITY DEFINER function + a plain UPDATE, so it's fully
-- reproducible against the disposable local Postgres this project has used
-- to validate every phase so far, and it reuses the *already-tested*
-- postgres_changes subscription on `players` (Phase 4) to broadcast the
-- resulting `connected` flip to every client — no new Realtime feature
-- needed. Trade-off: staleness detection lags by up to STALE_SECONDS
-- (below) rather than being instant. Documented rather than silently
-- swapped in without discussion — revisit if that lag proves too slow in
-- practice against a live project.
--
-- Staleness threshold: 20 seconds. The client calls heartbeat() and
-- mark_stale_players() together on the same interval — see
-- src/hooks/useHeartbeat.ts — every 8 seconds, so 20s is a little over two
-- missed heartbeats before someone is considered gone: enough slack for a
-- backgrounded mobile tab's throttled timers or a brief network hiccup,
-- short enough that a real drop is caught well within one question's
-- typical time limit (5-120s per games_time_limit_range).

create or replace function heartbeat(p_game_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  update players
    set connected = true, last_seen_at = now()
    where game_id = p_game_id and user_id = v_uid;

  if not found then
    raise exception 'You are not part of this game.' using errcode = '42501';
  end if;
end;
$$;


-- mark_stale_players: deliberately callable by *any* participant, not just
-- the host — the whole point of Phase 8 is that the host might be the one
-- who's gone, so this can't require the host to be the one to notice.
-- Purely a maintenance sweep: flips connected=false for anyone in this
-- game who's missed enough heartbeats. Idempotent (only touches rows that
-- are currently connected=true and actually stale) so calling it
-- redundantly from every client's timer, at slightly different times, is
-- harmless — last writer just re-sets the same value.
create or replace function mark_stale_players(p_game_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_stale_after constant interval := interval '20 seconds';
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  if not exists (select 1 from players where game_id = p_game_id and user_id = v_uid) then
    raise exception 'You are not part of this game.' using errcode = '42501';
  end if;

  update players
    set connected = false
    where game_id = p_game_id
      and connected = true
      and last_seen_at < now() - v_stale_after;
end;
$$;


-- claim_host: lets a remaining connected player take over as host once the
-- current host has gone stale (same 20s threshold as mark_stale_players,
-- checked independently here server-side rather than trusting the
-- caller's possibly-out-of-date view of `players.connected` — a client
-- could otherwise race a call in right as the real host reconnects).
-- New host is *not* whoever happened to click first among several who
-- might try — it's deterministically the earliest-joined currently
-- connected player (excluding the stale host), same "next-oldest
-- connected player" rule docs/MASTER_HANDOFF.md's Phase 8 section
-- proposed, so simultaneous claim attempts from two different clients
-- converge on the same answer rather than depending on request timing.
-- The caller only needs to be *a* participant (doesn't have to be the one
-- who ends up as the new host) — clicking "Become host" is really just
-- "run the reassignment", and GameRoom.tsx only shows that control to
-- non-host players once they can see (via the already-realtime-synced
-- `connected` flag) that the host looks gone.
create or replace function claim_host(p_game_id uuid)
returns table (
  out_new_host_player_id uuid,
  out_new_host_nickname text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
  v_host players%rowtype;
  v_candidate players%rowtype;
  v_stale_after constant interval := interval '20 seconds';
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  select * into v_game from games where id = p_game_id;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  if not exists (select 1 from players where game_id = p_game_id and user_id = v_uid) then
    raise exception 'You are not part of this game.' using errcode = '42501';
  end if;

  if v_game.status = 'FINISHED' then
    raise exception 'This game has already finished.' using errcode = 'P0001';
  end if;

  select * into v_host from players where game_id = p_game_id and is_host = true;
  if not found then
    -- Shouldn't happen (every game has exactly one host from create_game
    -- onward), but fail clearly rather than silently picking someone.
    raise exception 'This game has no host on record.' using errcode = 'P0007';
  end if;

  if v_host.user_id = v_uid then
    raise exception 'You are already the host.' using errcode = '22023';
  end if;

  if v_host.connected and v_host.last_seen_at >= now() - v_stale_after then
    raise exception 'The host is still connected.' using errcode = 'P0008';
  end if;

  select * into v_candidate
    from players
    where game_id = p_game_id
      and id <> v_host.id
      and connected = true
    order by joined_at asc
    limit 1;

  if not found then
    raise exception 'No other connected players are available to become host.'
      using errcode = 'P0009';
  end if;

  update players set is_host = false where id = v_host.id;
  update players set is_host = true where id = v_candidate.id;
  update games set host_user_id = v_candidate.user_id where id = p_game_id;

  return query select v_candidate.id, v_candidate.nickname;
end;
$$;


revoke execute on function heartbeat(uuid) from public;
revoke execute on function mark_stale_players(uuid) from public;
revoke execute on function claim_host(uuid) from public;

grant execute on function heartbeat(uuid) to authenticated;
grant execute on function mark_stale_players(uuid) to authenticated;
grant execute on function claim_host(uuid) to authenticated;


-- ===================================================================
-- FROM: supabase/migrations/0014_security_hardening.sql
-- ===================================================================
-- Pinoy Quiz — 0014: security + anti-cheat hardening (Phase 9)
--
-- Two things, matching the two concrete gaps docs/MASTER_HANDOFF.md's
-- Phase 9 section identified after reviewing the existing functions (this
-- migration does NOT touch submit_answer's scoring/timing logic — that
-- anti-cheat vector was already closed in Phase 6 by computing
-- response_time_ms server-side from games.question_started_at, never a
-- client-reported value; nothing here changes that).
--
-- 1. Rate limiting on every state-mutating SECURITY DEFINER function.
--    Decision (this determination was itself the Phase 9 work the handoff
--    asked for, not assumed either way going in): the SECURITY DEFINER +
--    RLS model closes *who can write what*, but it does nothing about
--    *how often* — every function's own correctness checks (right phase,
--    right caller, uniqueness constraints, etc.) still let a malicious
--    client call a function it's otherwise allowed to call as fast as a
--    tight loop can issue requests. Concretely, a bad client could:
--      - hammer `heartbeat`/`mark_stale_players` far faster than the 8s
--        interval the real client uses, burning DB connections/CPU on
--        pure overhead for no gain to that client (a real, if mild,
--        resource-exhaustion vector against a shared Postgres instance);
--      - spam `lookup_game_by_room_code` to brute-force 6-character room
--        codes (32^6 space, but still worth throttling — this is exactly
--        the enumeration vector docs/ARCHITECTURE.md's Security model
--        section flagged this function as needing "rate limiting" for,
--        left unaddressed when the function itself shipped in Phase 3);
--      - spam `create_game`/`join_game` to flood a room with junk rows or
--        exhaust the room-code space's collision retries.
--    None of these let a bad client corrupt *another* player's game state
--    (every function's existing checks still hold), so this is about
--    resource protection and enumeration resistance, not a data-integrity
--    hole — but it's a real gap worth closing, not a non-issue.
--
--    Mechanism: a small per-(user, action) sliding-window counter table +
--    one internal helper function, `enforce_rate_limit`, called at the top
--    of every mutating function (right after the existing "must be signed
--    in" check, before any real work happens). Deliberately NOT granted
--    EXECUTE to `authenticated` — it's meant to be called only from
--    *within* another SECURITY DEFINER function, the same
--    revoked-from-public-but-called-internally pattern
--    `generate_room_code()` already established in 0007_room_functions.sql.
--    Table is keyed on `auth.uid()`, so limits are per real user (browser's
--    anonymous auth session), not per game — a player in five simultaneous
--    games shares one budget per action, which is fine for this app's
--    actual usage pattern and simpler than per-game bookkeeping.
--
--    Chosen limits are generous multiples of each action's real client
--    cadence (see src/hooks/useHeartbeat.ts's 8s interval, GameRoom.tsx's
--    event-driven — not polled — fetches) so no legitimate client can ever
--    hit one, while still capping a tight-loop spammer at a small,
--    bounded multiple of normal traffic rather than unlimited.
--
-- 2. `claim_host` TOCTOU race (handoff item 2): the function read the
--    current host's `connected`/`last_seen_at` with a plain `select ...
--    into`, then later `update`d based on that snapshot. Between the read
--    and the write, nothing stopped the real host's own `heartbeat` call
--    from landing concurrently and refreshing `last_seen_at` — two
--    concurrent transactions could each read "stale" before either writes,
--    and the host gets demoted a moment after proving they're still there.
--    Fixed by taking `select ... for update` on the host's row up front,
--    so a concurrent `heartbeat` UPDATE on that same row and this
--    transaction serialize against each other instead of racing — whichever
--    commits first is what the other sees.

-- ---------------------------------------------------------------------
-- Rate limiting
-- ---------------------------------------------------------------------

create table rate_limit_hits (
  user_id uuid not null,
  action text not null,
  window_start timestamptz not null default now(),
  call_count integer not null default 1,
  primary key (user_id, action)
);

-- Defense in depth, matching every other table in this schema (0005/0006):
-- enable RLS with zero policies (blocks all client access outright) *and*
-- explicitly revoke table privileges, even though the only intended access
-- path is already the SECURITY DEFINER function below, which bypasses RLS
-- as the table owner regardless.
alter table rate_limit_hits enable row level security;
revoke all on rate_limit_hits from anon, authenticated;

-- enforce_rate_limit: internal helper, not part of the public API surface.
-- Upserts this (user, action) pair's counter: if the existing window has
-- expired, starts a fresh window at count 1; otherwise increments in
-- place. Raises once the incremented count exceeds p_max_calls. Single
-- upsert statement (no separate select-then-branch) so concurrent calls
-- from the same user racing each other still serialize correctly on the
-- table's primary key rather than both reading before either writes.
create or replace function enforce_rate_limit(
  p_action text,
  p_max_calls integer,
  p_window_seconds integer
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_row rate_limit_hits%rowtype;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  insert into rate_limit_hits as r (user_id, action, window_start, call_count)
  values (v_uid, p_action, now(), 1)
  on conflict (user_id, action) do update
    set call_count = case
        when r.window_start < now() - (p_window_seconds || ' seconds')::interval
          then 1
        else r.call_count + 1
      end,
      window_start = case
        when r.window_start < now() - (p_window_seconds || ' seconds')::interval
          then now()
        else r.window_start
      end
  returning * into v_row;

  if v_row.call_count > p_max_calls then
    raise exception 'You are doing that too fast — please slow down and try again in a moment.'
      using errcode = 'P0429';
  end if;
end;
$$;

revoke execute on function enforce_rate_limit(text, integer, integer) from public, anon, authenticated;

-- ---------------------------------------------------------------------
-- Apply enforce_rate_limit to every mutating (and the one
-- enumeration-sensitive read-only) function. Each `create or replace`
-- reproduces the function's existing body verbatim from its original
-- migration with exactly one addition: the rate-limit call, placed
-- immediately after the "must be signed in" check. Signatures are
-- unchanged, so the grants each function already has from its own
-- migration still apply — no grant/revoke statements needed here.
-- ---------------------------------------------------------------------

-- 0007_room_functions.sql: room-code enumeration is the concrete risk for
-- lookup_game_by_room_code (see header comment above); create_game/
-- join_game get the same generous "way above normal use" treatment as
-- everything else.

create or replace function create_game(
  p_category game_category_setting default 'random',
  p_difficulty game_difficulty_setting default 'mixed',
  p_question_count smallint default 10,
  p_time_limit_seconds smallint default 15,
  p_host_nickname text default 'Host'
)
returns table (
  out_game_id uuid,
  out_room_code text,
  out_player_id uuid
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_room_code text;
  v_game_id uuid;
  v_player_id uuid;
  v_nickname text := trim(p_host_nickname);
  v_attempt int := 0;
begin
  if v_uid is null then
    raise exception 'You must be signed in to create a game.' using errcode = '28000';
  end if;

  perform enforce_rate_limit('create_game', 10, 60);

  if char_length(v_nickname) < 1 or char_length(v_nickname) > 20 then
    raise exception 'Nickname must be between 1 and 20 characters.' using errcode = '22023';
  end if;

  loop
    v_attempt := v_attempt + 1;
    v_room_code := generate_room_code();
    begin
      insert into games (room_code, host_user_id, category, difficulty, question_count, time_limit_seconds)
      values (v_room_code, v_uid, p_category, p_difficulty, p_question_count, p_time_limit_seconds)
      returning id into v_game_id;
      exit;
    exception when unique_violation then
      if v_attempt >= 10 then
        raise exception 'Could not allocate a room code — please try again.' using errcode = '55000';
      end if;
    end;
  end loop;

  insert into players (game_id, user_id, nickname, is_host)
  values (v_game_id, v_uid, v_nickname, true)
  returning id into v_player_id;

  return query select v_game_id, v_room_code, v_player_id;
end;
$$;


create or replace function lookup_game_by_room_code(p_room_code text)
returns table (
  found boolean,
  status game_status,
  category game_category_setting,
  difficulty game_difficulty_setting,
  question_count smallint,
  time_limit_seconds smallint
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_game games%rowtype;
begin
  -- Not `stable` anymore now that it calls enforce_rate_limit (which
  -- writes) — Postgres would reject a volatile-underneath function marked
  -- `stable`, so the qualifier is dropped here rather than left
  -- inaccurate. This function was never actually side-effect-free from
  -- the caller's perspective anyway (every call still hits the DB to look
  -- up live game state), so losing the planner hint costs nothing
  -- meaningful.
  if auth.uid() is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  perform enforce_rate_limit('lookup_game_by_room_code', 20, 60);

  select * into v_game from games where room_code = upper(trim(p_room_code));
  if not found then
    return query select false, null::game_status, null::game_category_setting,
      null::game_difficulty_setting, null::smallint, null::smallint;
    return;
  end if;
  return query select true, v_game.status, v_game.category, v_game.difficulty,
    v_game.question_count, v_game.time_limit_seconds;
end;
$$;


create or replace function join_game(
  p_room_code text,
  p_nickname text
)
returns table (
  out_game_id uuid,
  out_player_id uuid,
  out_status game_status,
  out_is_host boolean,
  out_reconnected boolean
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
  v_existing players%rowtype;
  v_player_id uuid;
  v_nickname text := trim(p_nickname);
  v_player_count int;
  v_max_players constant int := 50;
begin
  if v_uid is null then
    raise exception 'You must be signed in to join a game.' using errcode = '28000';
  end if;

  perform enforce_rate_limit('join_game', 15, 60);

  if char_length(v_nickname) < 1 or char_length(v_nickname) > 20 then
    raise exception 'Nickname must be between 1 and 20 characters.' using errcode = '22023';
  end if;

  select * into v_game from games where room_code = upper(trim(p_room_code));
  if not found then
    raise exception 'That room code doesn''t exist.' using errcode = 'P0002';
  end if;

  select * into v_existing from players where game_id = v_game.id and user_id = v_uid;
  if found then
    update players
      set connected = true, last_seen_at = now()
      where id = v_existing.id
      returning id into v_player_id;
    return query select v_game.id, v_player_id, v_game.status, v_existing.is_host, true;
    return;
  end if;

  if v_game.status <> 'WAITING' then
    raise exception 'This game has already started.' using errcode = 'P0001';
  end if;

  if exists (
    select 1 from players where game_id = v_game.id and lower(nickname) = lower(v_nickname)
  ) then
    raise exception 'That nickname is already taken in this room.' using errcode = '23505';
  end if;

  select count(*) into v_player_count from players where game_id = v_game.id;
  if v_player_count >= v_max_players then
    raise exception 'This room is full.' using errcode = '53400';
  end if;

  insert into players (game_id, user_id, nickname, is_host)
  values (v_game.id, v_uid, v_nickname, false)
  returning id into v_player_id;

  return query select v_game.id, v_player_id, v_game.status, false, false;
end;
$$;


-- 0009_lobby_functions.sql

create or replace function remove_player(p_player_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_target players%rowtype;
  v_game games%rowtype;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  perform enforce_rate_limit('remove_player', 30, 60);

  select * into v_target from players where id = p_player_id;
  if not found then
    raise exception 'That player has already left the room.' using errcode = 'P0002';
  end if;

  select * into v_game from games where id = v_target.game_id;

  if v_game.host_user_id <> v_uid then
    raise exception 'Only the host can remove players.' using errcode = '42501';
  end if;

  if v_target.user_id = v_uid then
    raise exception 'You can''t remove yourself — end the game instead.' using errcode = '22023';
  end if;

  delete from players where id = p_player_id;
end;
$$;


-- 0010_game_engine.sql

create or replace function start_game(p_game_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
  v_player_count int;
  v_category_filter text;
  v_difficulty_filter text;
  v_question_ids uuid[];
  v_qid uuid;
  v_order smallint := 0;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  perform enforce_rate_limit('start_game', 10, 30);

  select * into v_game from games where id = p_game_id;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  if v_game.host_user_id <> v_uid then
    raise exception 'Only the host can start the game.' using errcode = '42501';
  end if;

  if v_game.status <> 'WAITING' then
    raise exception 'This game has already started.' using errcode = 'P0001';
  end if;

  select count(*) into v_player_count from players where game_id = p_game_id;
  if v_player_count < 1 then
    raise exception 'You need at least one player to start.' using errcode = 'P0004';
  end if;

  v_category_filter := nullif(v_game.category::text, 'random');
  v_difficulty_filter := nullif(v_game.difficulty::text, 'mixed');

  select array_agg(id) into v_question_ids
  from (
    select id from questions
    where (v_category_filter is null or category::text = v_category_filter)
      and (v_difficulty_filter is null or difficulty::text = v_difficulty_filter)
    order by random()
    limit v_game.question_count
  ) sub;

  if v_question_ids is null or array_length(v_question_ids, 1) < v_game.question_count then
    raise exception 'Not enough questions available for these settings. Try Random category or Mixed difficulty.'
      using errcode = 'P0005';
  end if;

  foreach v_qid in array v_question_ids loop
    insert into game_questions (game_id, question_id, question_order, shuffle_map)
    values (
      p_game_id,
      v_qid,
      v_order,
      (select array(select x from unnest(array[0,1,2,3]::smallint[]) x order by random()))
    );
    v_order := v_order + 1;
  end loop;

  update games set status = 'COUNTDOWN', started_at = now() where id = p_game_id;
end;
$$;


create or replace function begin_first_question(p_game_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
  v_gq_id uuid;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  perform enforce_rate_limit('begin_first_question', 10, 10);

  select * into v_game from games where id = p_game_id;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  if v_game.host_user_id <> v_uid then
    raise exception 'Only the host can do that.' using errcode = '42501';
  end if;

  if v_game.status <> 'COUNTDOWN' then
    raise exception 'This game is not ready to begin.' using errcode = 'P0001';
  end if;

  select id into v_gq_id from game_questions
  where game_id = p_game_id and question_order = 0;

  if v_gq_id is null then
    raise exception 'No questions were prepared for this game.' using errcode = 'P0006';
  end if;

  update games
    set status = 'QUESTION',
        current_question_index = 0,
        current_question_id = v_gq_id,
        question_started_at = now()
    where id = p_game_id;
end;
$$;


-- 0011_answer_submission.sql

create or replace function submit_answer(p_game_id uuid, p_selected_option smallint)
returns table (
  out_is_correct boolean,
  out_points integer
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
  v_player players%rowtype;
  v_gq game_questions%rowtype;
  v_q questions%rowtype;
  v_correct_index smallint;
  v_correct_slot smallint;
  v_is_correct boolean;
  v_response_ms integer;
  v_time_limit_ms integer;
  v_scoring jsonb;
  v_speed_ratio numeric;
  v_speed_bonus integer;
  v_points integer;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  perform enforce_rate_limit('submit_answer', 15, 10);

  if p_selected_option is null or p_selected_option not between 0 and 3 then
    raise exception 'That is not a valid answer option.' using errcode = '22023';
  end if;

  select * into v_game from games where id = p_game_id;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  select * into v_player from players
    where game_id = p_game_id and user_id = v_uid;
  if not found then
    raise exception 'You are not part of this game.' using errcode = '42501';
  end if;

  if v_game.status <> 'QUESTION' or v_game.current_question_id is null then
    raise exception 'This question is no longer accepting answers.' using errcode = 'P0007';
  end if;

  if exists (
    select 1 from answers
    where game_id = p_game_id
      and player_id = v_player.id
      and question_id = (select question_id from game_questions where id = v_game.current_question_id)
  ) then
    raise exception 'You already answered this question.' using errcode = 'P0008';
  end if;

  select * into v_gq from game_questions where id = v_game.current_question_id;
  select * into v_q from questions where id = v_gq.question_id;

  v_correct_index := array_position(array['A','B','C','D'], v_q.correct_option::text) - 1;
  v_correct_slot := array_position(v_gq.shuffle_map, v_correct_index) - 1;
  v_is_correct := (p_selected_option = v_correct_slot);

  v_time_limit_ms := v_game.time_limit_seconds * 1000;
  v_response_ms := greatest(
    0,
    least(
      v_time_limit_ms,
      extract(epoch from (now() - v_game.question_started_at)) * 1000
    )
  )::integer;

  v_scoring := v_game.scoring_config;

  if v_is_correct then
    v_speed_ratio := 1 - (v_response_ms::numeric / greatest(v_time_limit_ms, 1));
    v_speed_bonus := round(
      (v_scoring->>'maxSpeedBonus')::numeric * greatest(0, least(1, v_speed_ratio))
    )::integer;
    v_points := (v_scoring->>'basePoints')::integer + v_speed_bonus;
  else
    v_points := (v_scoring->>'incorrectPoints')::integer;
  end if;

  insert into answers (
    game_id, player_id, question_id, selected_option,
    is_correct, response_time_ms, points
  ) values (
    p_game_id, v_player.id, v_q.id, p_selected_option,
    v_is_correct, v_response_ms, v_points
  );

  update players set score = score + v_points where id = v_player.id;

  return query select v_is_correct, v_points;
end;
$$;


create or replace function end_question(p_game_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
  v_gq game_questions%rowtype;
  v_no_answer_points integer;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  perform enforce_rate_limit('end_question', 10, 10);

  select * into v_game from games where id = p_game_id;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  if v_game.host_user_id <> v_uid then
    raise exception 'Only the host can do that.' using errcode = '42501';
  end if;

  if v_game.status <> 'QUESTION' or v_game.current_question_id is null then
    raise exception 'This game is not in the question phase.' using errcode = 'P0001';
  end if;

  select * into v_gq from game_questions where id = v_game.current_question_id;
  v_no_answer_points := (v_game.scoring_config->>'noAnswerPoints')::integer;

  insert into answers (game_id, player_id, question_id, selected_option, is_correct, response_time_ms, points)
  select p_game_id, p.id, v_gq.question_id, null, false, null, v_no_answer_points
  from players p
  where p.game_id = p_game_id
    and not exists (
      select 1 from answers a
      where a.game_id = p_game_id and a.player_id = p.id and a.question_id = v_gq.question_id
    );

  update games set status = 'REVEAL' where id = p_game_id;
end;
$$;


-- 0012_leaderboard.sql

create or replace function advance_to_leaderboard(p_game_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  perform enforce_rate_limit('advance_to_leaderboard', 10, 10);

  select * into v_game from games where id = p_game_id;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  if v_game.host_user_id <> v_uid then
    raise exception 'Only the host can do that.' using errcode = '42501';
  end if;

  if v_game.status <> 'REVEAL' then
    raise exception 'This game is not in the reveal phase.' using errcode = 'P0001';
  end if;

  update games set status = 'LEADERBOARD' where id = p_game_id;
end;
$$;


create or replace function advance_question(p_game_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
  v_next_index smallint;
  v_next_gq_id uuid;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  perform enforce_rate_limit('advance_question', 10, 10);

  select * into v_game from games where id = p_game_id;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  if v_game.host_user_id <> v_uid then
    raise exception 'Only the host can do that.' using errcode = '42501';
  end if;

  if v_game.status <> 'LEADERBOARD' then
    raise exception 'This game is not on the leaderboard screen.' using errcode = 'P0001';
  end if;

  v_next_index := v_game.current_question_index + 1;

  if v_next_index < v_game.question_count then
    select id into v_next_gq_id from game_questions
      where game_id = p_game_id and question_order = v_next_index;

    if v_next_gq_id is null then
      raise exception 'No questions were prepared for this game.' using errcode = 'P0006';
    end if;

    update games
      set status = 'QUESTION',
          current_question_index = v_next_index,
          current_question_id = v_next_gq_id,
          question_started_at = now()
      where id = p_game_id;
  else
    update games
      set status = 'FINISHED',
          finished_at = now()
      where id = p_game_id;
  end if;
end;
$$;


-- 0013_disconnect_reconnect.sql — rate limiting, plus the claim_host
-- for-update race fix described in this migration's header comment.

create or replace function heartbeat(p_game_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  perform enforce_rate_limit('heartbeat', 20, 30);

  update players
    set connected = true, last_seen_at = now()
    where game_id = p_game_id and user_id = v_uid;

  if not found then
    raise exception 'You are not part of this game.' using errcode = '42501';
  end if;
end;
$$;


create or replace function mark_stale_players(p_game_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_stale_after constant interval := interval '20 seconds';
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  perform enforce_rate_limit('mark_stale_players', 20, 30);

  if not exists (select 1 from players where game_id = p_game_id and user_id = v_uid) then
    raise exception 'You are not part of this game.' using errcode = '42501';
  end if;

  update players
    set connected = false
    where game_id = p_game_id
      and connected = true
      and last_seen_at < now() - v_stale_after;
end;
$$;


create or replace function claim_host(p_game_id uuid)
returns table (
  out_new_host_player_id uuid,
  out_new_host_nickname text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
  v_host players%rowtype;
  v_candidate players%rowtype;
  v_stale_after constant interval := interval '20 seconds';
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  perform enforce_rate_limit('claim_host', 8, 30);

  select * into v_game from games where id = p_game_id;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  if not exists (select 1 from players where game_id = p_game_id and user_id = v_uid) then
    raise exception 'You are not part of this game.' using errcode = '42501';
  end if;

  if v_game.status = 'FINISHED' then
    raise exception 'This game has already finished.' using errcode = 'P0001';
  end if;

  -- `for update` locks the current host's row for the rest of this
  -- transaction. A concurrent `heartbeat()` call from the real host does a
  -- plain `update ... where ...` against this same row, so it will block
  -- until this transaction commits or rolls back rather than racing it —
  -- whichever of the two actually commits first is what the other sees,
  -- closing the TOCTOU gap described in this migration's header comment
  -- (previously: read host as "stale" here, host's own heartbeat lands
  -- before the update below, host gets demoted anyway).
  select * into v_host from players
    where game_id = p_game_id and is_host = true
    for update;
  if not found then
    raise exception 'This game has no host on record.' using errcode = 'P0007';
  end if;

  if v_host.user_id = v_uid then
    raise exception 'You are already the host.' using errcode = '22023';
  end if;

  if v_host.connected and v_host.last_seen_at >= now() - v_stale_after then
    raise exception 'The host is still connected.' using errcode = 'P0008';
  end if;

  select * into v_candidate
    from players
    where game_id = p_game_id
      and id <> v_host.id
      and connected = true
    order by joined_at asc
    limit 1;

  if not found then
    raise exception 'No other connected players are available to become host.'
      using errcode = 'P0009';
  end if;

  update players set is_host = false where id = v_host.id;
  update players set is_host = true where id = v_candidate.id;
  update games set host_user_id = v_candidate.user_id where id = p_game_id;

  return query select v_candidate.id, v_candidate.nickname;
end;
$$;


-- ===================================================================
-- FROM: supabase/migrations/0015_automatic_mode_and_answer_behavior.sql
-- ===================================================================
-- Pinoy Quiz — 0015: Automatic game mode + configurable Answer Behavior
--
-- Two independent, orthogonal per-game settings, chosen at create_game time
-- (host-only, same as category/difficulty/question_count/time_limit_seconds):
--
--   game_mode        HOST_CONTROLLED (existing behavior, now named) |
--                     AUTOMATIC (new)
--   answer_behavior   LOCK_ON_SELECTION (existing behavior, now named) |
--                     CHANGE_UNTIL_TIMER_ENDS (new)
--
-- Both default to the pre-existing behavior, so every game already in
-- flight (or replayed against an older client build) keeps working exactly
-- as before — see "Backward compatibility" below.
--
-- ---------------------------------------------------------------------
-- 1. Automatic mode — mechanism
-- ---------------------------------------------------------------------
--
-- This project has no server-side cron/scheduled-function infrastructure
-- (no pg_cron extension, no Supabase Edge Functions anywhere in this repo
-- — see docs/ARCHITECTURE.md). Every write so far is a plain client-called
-- SECURITY DEFINER function; nothing runs on a timer inside Postgres
-- itself. So "the game must not depend on the host's browser to advance"
-- can't mean "a background job on the server does it" here — that
-- infrastructure doesn't exist in this stack and adding pg_cron/Edge
-- Functions is a hosting-platform decision out of scope for a feature
-- migration (and Phase 12 — production deployment — is explicitly the
-- next task, still unstarted).
--
-- Instead this reuses the exact pattern Phase 8 already established for
-- "the host might be the one who's gone" (mark_stale_players /
-- claim_host, see 0013_disconnect_reconnect.sql's header comment): a
-- single new function, auto_advance_game, that
--   - any participant can call, not just the host,
--   - is a pure no-op unless the relevant phase's server-anchored
--     timestamp shows real elapsed time past that phase's duration, and
--   - is safe to call redundantly and concurrently (see the `for update`
--     lock below) — calling it from every connected client's timer,
--     slightly out of sync with each other, is not just tolerated but the
--     whole point.
--
-- The client side (src/hooks/useAutoAdvance.ts) is the same shape as
-- useHeartbeat.ts: every connected client polls this on a short interval
-- whenever games.game_mode = 'AUTOMATIC' and the game hasn't finished.
-- Because ANY client does this — not just the host's — the game keeps
-- advancing as long as at least one participant's tab is open, even if
-- the host is the one who disconnected. That satisfies "host
-- disconnecting during Automatic Mode does not stop the game" honestly,
-- given what this stack actually has available, rather than promising a
-- true background-job guarantee this codebase has no way to deliver.
--
-- Phase timing: QUESTION already has a server-authoritative anchor
-- (games.question_started_at, used since Phase 5/6 for both the display
-- timer and submit_answer's response-time clamp — untouched here). The
-- three other timed phases (COUNTDOWN, REVEAL, LEADERBOARD) had no
-- anchor at all before this migration, because they were previously only
-- ever advanced by an explicit host click with no server-side duration.
-- A single new nullable column, games.phase_started_at, now serves all
-- three — set to now() at the moment each phase begins (start_game for
-- COUNTDOWN, end_question for REVEAL, advance_to_leaderboard for
-- LEADERBOARD) and left alone otherwise. It's harmless to set even for
-- Host-Controlled games — nothing reads it there.
--
-- Fixed phase durations (COUNTDOWN/REVEAL/LEADERBOARD are not
-- per-game-configurable settings — only QUESTION's duration is, via the
-- existing time_limit_seconds — so these are plain constants, same as
-- Phase 8's STALE_SECONDS or Phase 9's rate-limit numbers):
--   COUNTDOWN_SECONDS   3  — matches CountdownOverlay's existing default
--                            cosmetic countdown (`seconds = 3`), so the
--                            real automatic transition and the animation
--                            every client already sees land together.
--   REVEAL_SECONDS      6  — enough to actually read the correct answer
--                            and explanation before it moves on;
--                            RevealScreen has real content (explanation
--                            text, percent-correct) that a 2-3s flash
--                            wouldn't do justice to.
--   LEADERBOARD_SECONDS  5 — enough to see your rank change before the
--                            next question, shorter than REVEAL_SECONDS
--                            since there's less to read here.
--
-- ---------------------------------------------------------------------
-- 2. Answer Behavior — mechanism
-- ---------------------------------------------------------------------
--
-- LOCK_ON_SELECTION reproduces submit_answer's pre-existing body exactly
-- (single INSERT, `answers_one_per_player_per_question` rejects a
-- second attempt, mapped to the existing "You already answered this
-- question" friendly message).
--
-- CHANGE_UNTIL_TIMER_ENDS instead UPSERTs the same row (`on conflict
-- (game_id, player_id, question_id) do update`) — the unique constraint
-- that used to be a hard "one submission ever" rule becomes the natural
-- upsert target for "this player's current answer to this question",
-- with each new selection recomputing correctness/points from scratch
-- and replacing the previous one, never inserting a second row (so
-- get_answer_reveal's is_correct/points lookup and end_question's
-- "already answered" exists-check both keep working unmodified — neither
-- was touched by this migration). players.score is adjusted by the
-- *delta* between the new and previous points on a change, not
-- incremented again by the full new amount, so switching an answer never
-- double-counts.
--
-- Both behaviors share one new hard cutoff: submit_answer now rejects a
-- submission (or change) once real elapsed time since
-- games.question_started_at has actually passed time_limit_seconds, even
-- if games.status hasn't flipped to REVEAL yet. Previously the only gate
-- was `status = 'QUESTION'`, which is fine when a host clicks
-- end_question as soon as the display timer hits zero, but
-- CHANGE_UNTIL_TIMER_ENDS specifically invites a player to keep tapping
-- right up to zero — closing the small "status hasn't flipped yet" window
-- between the clock actually running out and end_question/auto_advance_game
-- actually landing matters more once changing-until-the-wire is the
-- intended, encouraged interaction rather than an edge case. This applies
-- to LOCK_ON_SELECTION too (a strictly tighter check than before, never
-- looser), which is a deliberate small hardening, not a behavior this
-- migration was asked to change — flagged here rather than left silent.
--
-- ---------------------------------------------------------------------
-- 3. Backward compatibility
-- ---------------------------------------------------------------------
--
-- `game_mode` and `answer_behavior` are both `not null default` columns,
-- so every existing row (and every INSERT from an old, un-upgraded
-- client that doesn't know these params exist) lands on
-- HOST_CONTROLLED + LOCK_ON_SELECTION — exactly Phases 1-11's only
-- behavior. `create_game`'s two new parameters are appended at the end
-- of the argument list with defaults, so old positional/named calls
-- still work unchanged. No existing question, room, player, or answer
-- data is touched — this migration only adds columns/functions and
-- replaces function bodies (create_or_replace, never drop-and-lose-data).

-- ---------------------------------------------------------------------
-- Schema
-- ---------------------------------------------------------------------

create type game_mode as enum ('HOST_CONTROLLED', 'AUTOMATIC');
create type answer_behavior as enum ('LOCK_ON_SELECTION', 'CHANGE_UNTIL_TIMER_ENDS');

alter table games
  add column game_mode game_mode not null default 'HOST_CONTROLLED',
  add column answer_behavior answer_behavior not null default 'LOCK_ON_SELECTION',
  add column phase_started_at timestamptz;

comment on column games.phase_started_at is
  'Server-anchored start time for the current COUNTDOWN/REVEAL/LEADERBOARD phase, used only by auto_advance_game (Automatic mode). QUESTION uses the existing question_started_at instead — unchanged.';

-- create_game's signature grows by two (both defaulted) params, which
-- changes its argument-type identity — `create or replace` cannot widen a
-- function's own argument list, it can only replace a function with the
-- exact same one. Drop the old 5-arg signature explicitly, then create the
-- 7-arg replacement, rather than leaving both overloads callable.
drop function if exists create_game(game_category_setting, game_difficulty_setting, smallint, smallint, text);

create or replace function create_game(
  p_category game_category_setting default 'random',
  p_difficulty game_difficulty_setting default 'mixed',
  p_question_count smallint default 10,
  p_time_limit_seconds smallint default 15,
  p_host_nickname text default 'Host',
  p_game_mode game_mode default 'HOST_CONTROLLED',
  p_answer_behavior answer_behavior default 'LOCK_ON_SELECTION'
)
returns table (
  out_game_id uuid,
  out_room_code text,
  out_player_id uuid
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_room_code text;
  v_game_id uuid;
  v_player_id uuid;
  v_nickname text := trim(p_host_nickname);
  v_attempt int := 0;
begin
  if v_uid is null then
    raise exception 'You must be signed in to create a game.' using errcode = '28000';
  end if;

  perform enforce_rate_limit('create_game', 10, 60);

  if char_length(v_nickname) < 1 or char_length(v_nickname) > 20 then
    raise exception 'Nickname must be between 1 and 20 characters.' using errcode = '22023';
  end if;

  loop
    v_attempt := v_attempt + 1;
    v_room_code := generate_room_code();
    begin
      insert into games (
        room_code, host_user_id, category, difficulty, question_count,
        time_limit_seconds, game_mode, answer_behavior
      )
      values (
        v_room_code, v_uid, p_category, p_difficulty, p_question_count,
        p_time_limit_seconds, p_game_mode, p_answer_behavior
      )
      returning id into v_game_id;
      exit;
    exception when unique_violation then
      if v_attempt >= 10 then
        raise exception 'Could not allocate a room code — please try again.' using errcode = '55000';
      end if;
    end;
  end loop;

  insert into players (game_id, user_id, nickname, is_host)
  values (v_game_id, v_uid, v_nickname, true)
  returning id into v_player_id;

  return query select v_game_id, v_room_code, v_player_id;
end;
$$;

grant execute on function create_game(
  game_category_setting, game_difficulty_setting, smallint, smallint, text, game_mode, answer_behavior
) to authenticated;

-- ---------------------------------------------------------------------
-- start_game — unchanged behavior, +phase_started_at anchor for COUNTDOWN
-- ---------------------------------------------------------------------

create or replace function start_game(p_game_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
  v_player_count int;
  v_category_filter text;
  v_difficulty_filter text;
  v_question_ids uuid[];
  v_qid uuid;
  v_order smallint := 0;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  perform enforce_rate_limit('start_game', 10, 30);

  select * into v_game from games where id = p_game_id;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  if v_game.host_user_id <> v_uid then
    raise exception 'Only the host can start the game.' using errcode = '42501';
  end if;

  if v_game.status <> 'WAITING' then
    raise exception 'This game has already started.' using errcode = 'P0001';
  end if;

  select count(*) into v_player_count from players where game_id = p_game_id;
  if v_player_count < 1 then
    raise exception 'You need at least one player to start.' using errcode = 'P0004';
  end if;

  v_category_filter := nullif(v_game.category::text, 'random');
  v_difficulty_filter := nullif(v_game.difficulty::text, 'mixed');

  select array_agg(id) into v_question_ids
  from (
    select id from questions
    where (v_category_filter is null or category::text = v_category_filter)
      and (v_difficulty_filter is null or difficulty::text = v_difficulty_filter)
    order by random()
    limit v_game.question_count
  ) sub;

  if v_question_ids is null or array_length(v_question_ids, 1) < v_game.question_count then
    raise exception 'Not enough questions available for these settings. Try Random category or Mixed difficulty.'
      using errcode = 'P0005';
  end if;

  foreach v_qid in array v_question_ids loop
    insert into game_questions (game_id, question_id, question_order, shuffle_map)
    values (
      p_game_id,
      v_qid,
      v_order,
      (select array(select x from unnest(array[0,1,2,3]::smallint[]) x order by random()))
    );
    v_order := v_order + 1;
  end loop;

  update games set status = 'COUNTDOWN', started_at = now(), phase_started_at = now() where id = p_game_id;
end;
$$;

-- ---------------------------------------------------------------------
-- submit_answer — LOCK_ON_SELECTION unchanged; CHANGE_UNTIL_TIMER_ENDS
-- upserts; both gated by a real-elapsed-time cutoff in addition to the
-- existing status check (see header comment, section 2).
-- ---------------------------------------------------------------------

create or replace function submit_answer(p_game_id uuid, p_selected_option smallint)
returns table (
  out_is_correct boolean,
  out_points integer
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
  v_player players%rowtype;
  v_gq game_questions%rowtype;
  v_q questions%rowtype;
  v_correct_index smallint;
  v_correct_slot smallint;
  v_is_correct boolean;
  v_response_ms integer;
  v_time_limit_ms integer;
  v_scoring jsonb;
  v_speed_ratio numeric;
  v_speed_bonus integer;
  v_points integer;
  v_existing answers%rowtype;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  perform enforce_rate_limit('submit_answer', 30, 10);

  if p_selected_option is null or p_selected_option not between 0 and 3 then
    raise exception 'That is not a valid answer option.' using errcode = '22023';
  end if;

  select * into v_game from games where id = p_game_id;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  select * into v_player from players
    where game_id = p_game_id and user_id = v_uid;
  if not found then
    raise exception 'You are not part of this game.' using errcode = '42501';
  end if;

  if v_game.status <> 'QUESTION' or v_game.current_question_id is null then
    raise exception 'This question is no longer accepting answers.' using errcode = 'P0007';
  end if;

  -- Real-elapsed-time cutoff — see this migration's header comment,
  -- section 2, for why this is checked in addition to `status = 'QUESTION'`.
  if now() >= v_game.question_started_at + make_interval(secs => v_game.time_limit_seconds) then
    raise exception 'This question is no longer accepting answers.' using errcode = 'P0007';
  end if;

  select * into v_gq from game_questions where id = v_game.current_question_id;
  select * into v_q from questions where id = v_gq.question_id;

  select * into v_existing from answers
    where game_id = p_game_id
      and player_id = v_player.id
      and question_id = v_q.id;

  if found then
    if v_game.answer_behavior = 'LOCK_ON_SELECTION' then
      raise exception 'You already answered this question.' using errcode = 'P0008';
    end if;
    -- CHANGE_UNTIL_TIMER_ENDS: fall through and upsert below.
  end if;

  v_correct_index := array_position(array['A','B','C','D'], v_q.correct_option::text) - 1;
  v_correct_slot := array_position(v_gq.shuffle_map, v_correct_index) - 1;
  v_is_correct := (p_selected_option = v_correct_slot);

  v_time_limit_ms := v_game.time_limit_seconds * 1000;
  v_response_ms := greatest(
    0,
    least(
      v_time_limit_ms,
      extract(epoch from (now() - v_game.question_started_at)) * 1000
    )
  )::integer;

  v_scoring := v_game.scoring_config;

  if v_is_correct then
    v_speed_ratio := 1 - (v_response_ms::numeric / greatest(v_time_limit_ms, 1));
    v_speed_bonus := round(
      (v_scoring->>'maxSpeedBonus')::numeric * greatest(0, least(1, v_speed_ratio))
    )::integer;
    v_points := (v_scoring->>'basePoints')::integer + v_speed_bonus;
  else
    v_points := (v_scoring->>'incorrectPoints')::integer;
  end if;

  insert into answers (
    game_id, player_id, question_id, selected_option,
    is_correct, response_time_ms, points
  ) values (
    p_game_id, v_player.id, v_q.id, p_selected_option,
    v_is_correct, v_response_ms, v_points
  )
  on conflict (game_id, player_id, question_id) do update
    set selected_option = excluded.selected_option,
        is_correct = excluded.is_correct,
        response_time_ms = excluded.response_time_ms,
        points = excluded.points;

  -- Adjust the player's running total by the *delta* from whatever this
  -- exact submission previously scored (0 on a brand-new answer), never
  -- by the full new amount again — otherwise changing an answer under
  -- CHANGE_UNTIL_TIMER_ENDS would double-count every intermediate pick.
  update players
    set score = score + (v_points - coalesce(v_existing.points, 0))
    where id = v_player.id;

  return query select v_is_correct, v_points;
end;
$$;

-- ---------------------------------------------------------------------
-- end_question — unchanged behavior, +phase_started_at anchor for REVEAL
-- ---------------------------------------------------------------------

create or replace function end_question(p_game_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
  v_gq game_questions%rowtype;
  v_no_answer_points integer;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  perform enforce_rate_limit('end_question', 10, 10);

  select * into v_game from games where id = p_game_id;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  if v_game.host_user_id <> v_uid then
    raise exception 'Only the host can do that.' using errcode = '42501';
  end if;

  if v_game.status <> 'QUESTION' or v_game.current_question_id is null then
    raise exception 'This game is not in the question phase.' using errcode = 'P0001';
  end if;

  select * into v_gq from game_questions where id = v_game.current_question_id;
  v_no_answer_points := (v_game.scoring_config->>'noAnswerPoints')::integer;

  insert into answers (game_id, player_id, question_id, selected_option, is_correct, response_time_ms, points)
  select p_game_id, p.id, v_gq.question_id, null, false, null, v_no_answer_points
  from players p
  where p.game_id = p_game_id
    and not exists (
      select 1 from answers a
      where a.game_id = p_game_id and a.player_id = p.id and a.question_id = v_gq.question_id
    );

  update games set status = 'REVEAL', phase_started_at = now() where id = p_game_id;
end;
$$;

-- ---------------------------------------------------------------------
-- advance_to_leaderboard — unchanged behavior, +phase_started_at anchor
-- ---------------------------------------------------------------------

create or replace function advance_to_leaderboard(p_game_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  perform enforce_rate_limit('advance_to_leaderboard', 10, 10);

  select * into v_game from games where id = p_game_id;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  if v_game.host_user_id <> v_uid then
    raise exception 'Only the host can do that.' using errcode = '42501';
  end if;

  if v_game.status <> 'REVEAL' then
    raise exception 'This game is not in the reveal phase.' using errcode = 'P0001';
  end if;

  update games set status = 'LEADERBOARD', phase_started_at = now() where id = p_game_id;
end;
$$;

-- advance_question (LEADERBOARD -> next QUESTION | FINISHED) needs no
-- change at all — QUESTION already anchors on question_started_at, and
-- FINISHED isn't a timed phase auto_advance_game ever waits on.

-- ---------------------------------------------------------------------
-- auto_advance_game — new. Automatic-mode-only, any-participant-callable
-- equivalent of begin_first_question / end_question / advance_to_leaderboard
-- / advance_question, gated on real server-elapsed time instead of a host
-- click. See this migration's header comment, section 1, for the full
-- design rationale.
-- ---------------------------------------------------------------------

create or replace function auto_advance_game(p_game_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
  v_gq game_questions%rowtype;
  v_no_answer_points integer;
  v_next_index smallint;
  v_next_gq_id uuid;
  countdown_seconds constant int := 3;   -- matches CountdownOverlay's cosmetic default
  reveal_seconds constant int := 6;
  leaderboard_seconds constant int := 5;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  perform enforce_rate_limit('auto_advance_game', 60, 20);

  -- `for update` locks the games row for the rest of this transaction, so
  -- concurrent calls from several clients' polling timers (the expected,
  -- normal case — see header comment) serialize against each other rather
  -- than racing: whichever commits first performs the transition and
  -- moves `status`/the relevant `*_started_at` column past the condition
  -- below, so every other concurrent caller's own re-read after acquiring
  -- the lock sees the already-updated row and falls through to a no-op.
  -- Same fix as claim_host's TOCTOU close in 0014_security_hardening.sql.
  select * into v_game from games where id = p_game_id for update;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  if not exists (select 1 from players where game_id = p_game_id and user_id = v_uid) then
    raise exception 'You are not part of this game.' using errcode = '42501';
  end if;

  -- Not an Automatic-mode game, or nothing timed to advance right now —
  -- both are ordinary, expected outcomes of a client polling on a plain
  -- interval (see useAutoAdvance.ts), not errors.
  if v_game.game_mode <> 'AUTOMATIC' then
    return;
  end if;

  if v_game.status = 'COUNTDOWN' then
    if v_game.phase_started_at is null
      or now() < v_game.phase_started_at + make_interval(secs => countdown_seconds)
    then
      return;
    end if;

    select id into v_next_gq_id from game_questions
      where game_id = p_game_id and question_order = 0;

    if v_next_gq_id is null then
      raise exception 'No questions were prepared for this game.' using errcode = 'P0006';
    end if;

    update games
      set status = 'QUESTION',
          current_question_index = 0,
          current_question_id = v_next_gq_id,
          question_started_at = now()
      where id = p_game_id;
    return;
  end if;

  if v_game.status = 'QUESTION' then
    if v_game.question_started_at is null
      or now() < v_game.question_started_at + make_interval(secs => v_game.time_limit_seconds)
    then
      return;
    end if;

    select * into v_gq from game_questions where id = v_game.current_question_id;
    v_no_answer_points := (v_game.scoring_config->>'noAnswerPoints')::integer;

    insert into answers (game_id, player_id, question_id, selected_option, is_correct, response_time_ms, points)
    select p_game_id, p.id, v_gq.question_id, null, false, null, v_no_answer_points
    from players p
    where p.game_id = p_game_id
      and not exists (
        select 1 from answers a
        where a.game_id = p_game_id and a.player_id = p.id and a.question_id = v_gq.question_id
      );

    update games set status = 'REVEAL', phase_started_at = now() where id = p_game_id;
    return;
  end if;

  if v_game.status = 'REVEAL' then
    if v_game.phase_started_at is null
      or now() < v_game.phase_started_at + make_interval(secs => reveal_seconds)
    then
      return;
    end if;

    update games set status = 'LEADERBOARD', phase_started_at = now() where id = p_game_id;
    return;
  end if;

  if v_game.status = 'LEADERBOARD' then
    if v_game.phase_started_at is null
      or now() < v_game.phase_started_at + make_interval(secs => leaderboard_seconds)
    then
      return;
    end if;

    v_next_index := v_game.current_question_index + 1;

    if v_next_index < v_game.question_count then
      select id into v_next_gq_id from game_questions
        where game_id = p_game_id and question_order = v_next_index;

      if v_next_gq_id is null then
        raise exception 'No questions were prepared for this game.' using errcode = 'P0006';
      end if;

      update games
        set status = 'QUESTION',
            current_question_index = v_next_index,
            current_question_id = v_next_gq_id,
            question_started_at = now()
        where id = p_game_id;
    else
      update games
        set status = 'FINISHED',
            finished_at = now()
        where id = p_game_id;
    end if;
    return;
  end if;

  -- WAITING/FINISHED: nothing to auto-advance.
end;
$$;

revoke execute on function auto_advance_game(uuid) from public;
grant execute on function auto_advance_game(uuid) to authenticated;


-- ===================================================================
-- FROM: supabase/migrations/0016_play_again_and_no_repeat_questions.sql
-- ===================================================================
-- Pinoy Quiz — 0016: Play Again (rematch in the same room) + avoid
-- repeating questions
--
-- Two related bugs reported against the live app, both fixed together
-- because the second fix only works cleanly once the first exists:
--
-- 1. "Play Again" (Results.tsx) just linked to /create — a brand new room,
--    new room code, new invite link, every player (including the host)
--    having to rejoin and retype their nickname. There was no way to
--    replay in the same room at all.
-- 2. Every game (including a hypothetical rematch) drew its question set
--    with a single `order by random() limit question_count` against the
--    *entire* filtered pool, with zero memory of what any previous game
--    — in this room or otherwise — had already used. With a real pool
--    that's often much smaller than 240 once category/difficulty narrow
--    it down (e.g. a single category+difficulty combo can be well under
--    20 questions), repeats inside a handful of replays are expected, not
--    a bug in the random() call itself — the actual bug is that nothing
--    ever *avoided* them.
--
-- ---------------------------------------------------------------------
-- Design: same games.id and room_code, a new round_number
-- ---------------------------------------------------------------------
--
-- The fix for (1) is deliberately NOT "create a new games row and give it
-- the same room_code" — room_code has a global unique index
-- (0003_tables.sql), so two live rows could never share one anyway, and
-- reusing a code only after the first row's `players` were migrated over
-- would be a much bigger, riskier change than this bug calls for.
--
-- Instead, `play_again()` resets the SAME games row back to WAITING and
-- increments a new `games.round_number` column. Since `players.game_id`
-- never changes, every player's row — nickname, is_host, connected,
-- everything — simply carries over untouched. No rejoin, no re-typed
-- nickname, no new room code to re-share: the room the players are
-- already sitting in (and already subscribed to via Realtime) just goes
-- back to its lobby. `start_game` (unchanged host action) is what the
-- host clicks to kick off the next round, exactly like the first one.
--
-- `round_number` also solves (2) directly: `game_questions` and `answers`
-- both gain the same column, and `start_game`'s question-selection query
-- now excludes every `question_id` already used anywhere in this
-- `game_id`'s history (across all previous rounds) before falling back to
-- allowing repeats — only once the "never used in this room" pool is
-- actually exhausted. A game's first-ever round has no history yet, so
-- this is a no-op there; it only changes behavior from round 2 onward.
--
-- Every function that reads/writes `game_questions`/`answers` scoped to
-- "the current question" now also scopes by `round_number` — without
-- that, a question repeating in round 3 would collide with its own
-- leftover `answers` row from round 1 (wrong `already answered` rejection
-- under LOCK_ON_SELECTION, wrong upsert target under
-- CHANGE_UNTIL_TIMER_ENDS, wrong percent-correct in `get_answer_reveal`,
-- wrong score_delta in `get_leaderboard`). Existing rows from prior rounds
-- are never deleted — they're both harmless history and exactly the data
-- `start_game`'s "already used" exclusion query depends on.
--
-- `players.score` is reset to 0 for a new round — "Play Again" starts a
-- fresh scoreboard, not a running cumulative total across rounds. If a
-- future request wants a cumulative "best of N rounds" mode instead,
-- that's a different, larger feature (persistent per-round history UI,
-- an aggregate leaderboard function) — not assumed here.
--
-- ---------------------------------------------------------------------
-- Backward compatibility
-- ---------------------------------------------------------------------
--
-- `round_number` is a `not null default 1` column on all three tables, so
-- every existing row reads as round 1 — exactly what it already was.
-- `start_game`'s new "exclude previously-used questions" clause is a
-- no-op for any game_id with no game_questions history yet (every game
-- that has never been replayed), so round-1 behavior for both new and
-- already-in-flight games is unchanged other than the query shape itself.

-- ---------------------------------------------------------------------
-- Schema
-- ---------------------------------------------------------------------

alter table games
  add column round_number smallint not null default 1,
  add constraint games_round_number_positive check (round_number >= 1);

alter table game_questions
  add column round_number smallint not null default 1;

alter table game_questions
  drop constraint game_questions_order_unique,
  drop constraint game_questions_no_dupes,
  add constraint game_questions_order_unique unique (game_id, round_number, question_order),
  add constraint game_questions_no_dupes unique (game_id, round_number, question_id);

alter table answers
  add column round_number smallint not null default 1;

alter table answers
  drop constraint answers_one_per_player_per_question,
  add constraint answers_one_per_player_per_question unique (game_id, round_number, player_id, question_id);

drop index if exists answers_game_question_idx;
create index answers_game_question_idx on answers (game_id, round_number, question_id);

-- ---------------------------------------------------------------------
-- start_game — now round_number-aware and repeat-avoiding. Everything
-- else (auth/host/status/player-count checks, phase_started_at anchor
-- from 0015) is unchanged.
-- ---------------------------------------------------------------------

create or replace function start_game(p_game_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
  v_player_count int;
  v_category_filter text;
  v_difficulty_filter text;
  v_total_available int;
  v_fresh_ids uuid[];
  v_topup_ids uuid[];
  v_question_ids uuid[];
  v_qid uuid;
  v_order smallint := 0;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  perform enforce_rate_limit('start_game', 10, 30);

  select * into v_game from games where id = p_game_id;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  if v_game.host_user_id <> v_uid then
    raise exception 'Only the host can start the game.' using errcode = '42501';
  end if;

  if v_game.status <> 'WAITING' then
    raise exception 'This game has already started.' using errcode = 'P0001';
  end if;

  select count(*) into v_player_count from players where game_id = p_game_id;
  if v_player_count < 1 then
    raise exception 'You need at least one player to start.' using errcode = 'P0004';
  end if;

  v_category_filter := nullif(v_game.category::text, 'random');
  v_difficulty_filter := nullif(v_game.difficulty::text, 'mixed');

  select count(*) into v_total_available
  from questions
  where (v_category_filter is null or category::text = v_category_filter)
    and (v_difficulty_filter is null or difficulty::text = v_difficulty_filter);

  if v_total_available < v_game.question_count then
    raise exception 'Not enough questions available for these settings. Try Random category or Mixed difficulty.'
      using errcode = 'P0005';
  end if;

  -- Prefer questions never used before anywhere in this room's history
  -- (any earlier round of this same game_id) — see this migration's
  -- header comment. A brand-new game has no history, so this simply
  -- draws from the full filtered pool, same as before this migration.
  select array_agg(id) into v_fresh_ids
  from (
    select id from questions
    where (v_category_filter is null or category::text = v_category_filter)
      and (v_difficulty_filter is null or difficulty::text = v_difficulty_filter)
      and id not in (select question_id from game_questions where game_id = p_game_id)
    order by random()
    limit v_game.question_count
  ) sub;

  v_question_ids := coalesce(v_fresh_ids, array[]::uuid[]);

  if coalesce(array_length(v_question_ids, 1), 0) < v_game.question_count then
    -- The "never used in this room" pool ran out (a small category pool,
    -- or a room several rounds deep) — top up from the full filtered
    -- pool, excluding whatever this draw already picked so a single
    -- round never shows the same question twice. A top-up pick MAY
    -- repeat a question from an earlier round; that's expected and only
    -- happens once every fresh option has already been used.
    select array_agg(id) into v_topup_ids
    from (
      select id from questions
      where (v_category_filter is null or category::text = v_category_filter)
        and (v_difficulty_filter is null or difficulty::text = v_difficulty_filter)
        and not (id = any(v_question_ids))
      order by random()
      limit (v_game.question_count - coalesce(array_length(v_question_ids, 1), 0))
    ) sub;
    v_question_ids := v_question_ids || coalesce(v_topup_ids, array[]::uuid[]);
  end if;

  foreach v_qid in array v_question_ids loop
    insert into game_questions (game_id, question_id, question_order, round_number, shuffle_map)
    values (
      p_game_id,
      v_qid,
      v_order,
      v_game.round_number,
      (select array(select x from unnest(array[0,1,2,3]::smallint[]) x order by random()))
    );
    v_order := v_order + 1;
  end loop;

  update games set status = 'COUNTDOWN', started_at = now(), phase_started_at = now() where id = p_game_id;
end;
$$;

-- ---------------------------------------------------------------------
-- submit_answer — round-scoped existing-answer check/upsert target.
-- ---------------------------------------------------------------------

create or replace function submit_answer(p_game_id uuid, p_selected_option smallint)
returns table (
  out_is_correct boolean,
  out_points integer
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
  v_player players%rowtype;
  v_gq game_questions%rowtype;
  v_q questions%rowtype;
  v_correct_index smallint;
  v_correct_slot smallint;
  v_is_correct boolean;
  v_response_ms integer;
  v_time_limit_ms integer;
  v_scoring jsonb;
  v_speed_ratio numeric;
  v_speed_bonus integer;
  v_points integer;
  v_existing answers%rowtype;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  perform enforce_rate_limit('submit_answer', 30, 10);

  if p_selected_option is null or p_selected_option not between 0 and 3 then
    raise exception 'That is not a valid answer option.' using errcode = '22023';
  end if;

  select * into v_game from games where id = p_game_id;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  select * into v_player from players
    where game_id = p_game_id and user_id = v_uid;
  if not found then
    raise exception 'You are not part of this game.' using errcode = '42501';
  end if;

  if v_game.status <> 'QUESTION' or v_game.current_question_id is null then
    raise exception 'This question is no longer accepting answers.' using errcode = 'P0007';
  end if;

  if now() >= v_game.question_started_at + make_interval(secs => v_game.time_limit_seconds) then
    raise exception 'This question is no longer accepting answers.' using errcode = 'P0007';
  end if;

  select * into v_gq from game_questions where id = v_game.current_question_id;
  select * into v_q from questions where id = v_gq.question_id;

  select * into v_existing from answers
    where game_id = p_game_id
      and round_number = v_game.round_number
      and player_id = v_player.id
      and question_id = v_q.id;

  if found then
    if v_game.answer_behavior = 'LOCK_ON_SELECTION' then
      raise exception 'You already answered this question.' using errcode = 'P0008';
    end if;
    -- CHANGE_UNTIL_TIMER_ENDS: fall through and upsert below.
  end if;

  v_correct_index := array_position(array['A','B','C','D'], v_q.correct_option::text) - 1;
  v_correct_slot := array_position(v_gq.shuffle_map, v_correct_index) - 1;
  v_is_correct := (p_selected_option = v_correct_slot);

  v_time_limit_ms := v_game.time_limit_seconds * 1000;
  v_response_ms := greatest(
    0,
    least(
      v_time_limit_ms,
      extract(epoch from (now() - v_game.question_started_at)) * 1000
    )
  )::integer;

  v_scoring := v_game.scoring_config;

  if v_is_correct then
    v_speed_ratio := 1 - (v_response_ms::numeric / greatest(v_time_limit_ms, 1));
    v_speed_bonus := round(
      (v_scoring->>'maxSpeedBonus')::numeric * greatest(0, least(1, v_speed_ratio))
    )::integer;
    v_points := (v_scoring->>'basePoints')::integer + v_speed_bonus;
  else
    v_points := (v_scoring->>'incorrectPoints')::integer;
  end if;

  insert into answers (
    game_id, round_number, player_id, question_id, selected_option,
    is_correct, response_time_ms, points
  ) values (
    p_game_id, v_game.round_number, v_player.id, v_q.id, p_selected_option,
    v_is_correct, v_response_ms, v_points
  )
  on conflict (game_id, round_number, player_id, question_id) do update
    set selected_option = excluded.selected_option,
        is_correct = excluded.is_correct,
        response_time_ms = excluded.response_time_ms,
        points = excluded.points;

  update players
    set score = score + (v_points - coalesce(v_existing.points, 0))
    where id = v_player.id;

  return query select v_is_correct, v_points;
end;
$$;

-- ---------------------------------------------------------------------
-- end_question — round-scoped no-answer insert/check.
-- ---------------------------------------------------------------------

create or replace function end_question(p_game_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
  v_gq game_questions%rowtype;
  v_no_answer_points integer;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  perform enforce_rate_limit('end_question', 10, 10);

  select * into v_game from games where id = p_game_id;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  if v_game.host_user_id <> v_uid then
    raise exception 'Only the host can do that.' using errcode = '42501';
  end if;

  if v_game.status <> 'QUESTION' or v_game.current_question_id is null then
    raise exception 'This game is not in the question phase.' using errcode = 'P0001';
  end if;

  select * into v_gq from game_questions where id = v_game.current_question_id;
  v_no_answer_points := (v_game.scoring_config->>'noAnswerPoints')::integer;

  insert into answers (game_id, round_number, player_id, question_id, selected_option, is_correct, response_time_ms, points)
  select p_game_id, v_game.round_number, p.id, v_gq.question_id, null, false, null, v_no_answer_points
  from players p
  where p.game_id = p_game_id
    and not exists (
      select 1 from answers a
      where a.game_id = p_game_id
        and a.round_number = v_game.round_number
        and a.player_id = p.id
        and a.question_id = v_gq.question_id
    );

  update games set status = 'REVEAL', phase_started_at = now() where id = p_game_id;
end;
$$;

-- ---------------------------------------------------------------------
-- get_answer_reveal — round-scoped own-answer lookup and percent-correct.
-- ---------------------------------------------------------------------

create or replace function get_answer_reveal(p_game_id uuid)
returns table (
  out_question_id uuid,
  out_correct_option smallint,
  out_correct_text text,
  out_explanation text,
  out_your_answer smallint,
  out_your_points integer,
  out_was_correct boolean,
  out_percent_correct numeric
)
language plpgsql
security definer
stable
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
  v_player players%rowtype;
  v_gq game_questions%rowtype;
  v_q questions%rowtype;
  v_opts text[];
  v_correct_index smallint;
  v_correct_slot smallint;
  v_answer answers%rowtype;
  v_total_players int;
  v_correct_count int;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  select * into v_game from games where id = p_game_id;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  select * into v_player from players
    where game_id = p_game_id and user_id = v_uid;
  if not found then
    raise exception 'You are not part of this game.' using errcode = '42501';
  end if;

  if v_game.status <> 'REVEAL' or v_game.current_question_id is null then
    return;
  end if;

  select * into v_gq from game_questions where id = v_game.current_question_id;
  select * into v_q from questions where id = v_gq.question_id;
  v_opts := array[v_q.option_a, v_q.option_b, v_q.option_c, v_q.option_d];

  v_correct_index := array_position(array['A','B','C','D'], v_q.correct_option::text) - 1;
  v_correct_slot := array_position(v_gq.shuffle_map, v_correct_index) - 1;

  select * into v_answer from answers
    where game_id = p_game_id
      and round_number = v_game.round_number
      and player_id = v_player.id
      and question_id = v_q.id;

  select count(*) into v_total_players from players where game_id = p_game_id;
  select count(*) into v_correct_count from answers
    where game_id = p_game_id
      and round_number = v_game.round_number
      and question_id = v_q.id
      and is_correct;

  return query select
    v_q.id,
    v_correct_slot,
    v_opts[v_correct_index + 1],
    v_q.explanation,
    v_answer.selected_option,
    coalesce(v_answer.points, 0),
    coalesce(v_answer.is_correct, false),
    case when v_total_players > 0
      then round(100.0 * v_correct_count / v_total_players, 1)
      else 0
    end;
end;
$$;

-- ---------------------------------------------------------------------
-- get_leaderboard — round-scoped score_delta join.
-- ---------------------------------------------------------------------

create or replace function get_leaderboard(p_game_id uuid)
returns table (
  out_player_id uuid,
  out_nickname text,
  out_score integer,
  out_rank bigint,
  out_score_delta integer
)
language plpgsql
security definer
stable
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
  v_last_question_id uuid;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  select * into v_game from games where id = p_game_id;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  if not exists (select 1 from players where game_id = p_game_id and user_id = v_uid) then
    raise exception 'You are not part of this game.' using errcode = '42501';
  end if;

  if v_game.current_question_id is not null then
    select question_id into v_last_question_id
    from game_questions where id = v_game.current_question_id;
  end if;

  return query
    select
      p.id,
      p.nickname,
      p.score,
      rank() over (order by p.score desc, p.joined_at asc),
      coalesce(a.points, 0)
    from players p
    left join answers a
      on a.player_id = p.id
      and a.game_id = p_game_id
      and a.round_number = v_game.round_number
      and a.question_id = v_last_question_id
    where p.game_id = p_game_id
    order by rank() over (order by p.score desc, p.joined_at asc);
end;
$$;

-- ---------------------------------------------------------------------
-- auto_advance_game — round-scoped no-answer insert (its QUESTION branch
-- duplicates end_question's logic — see 0015's header comment for why).
-- Everything else is unchanged from 0015.
-- ---------------------------------------------------------------------

create or replace function auto_advance_game(p_game_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
  v_gq game_questions%rowtype;
  v_no_answer_points integer;
  v_next_index smallint;
  v_next_gq_id uuid;
  countdown_seconds constant int := 3;
  reveal_seconds constant int := 6;
  leaderboard_seconds constant int := 5;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  perform enforce_rate_limit('auto_advance_game', 60, 20);

  select * into v_game from games where id = p_game_id for update;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  if not exists (select 1 from players where game_id = p_game_id and user_id = v_uid) then
    raise exception 'You are not part of this game.' using errcode = '42501';
  end if;

  if v_game.game_mode <> 'AUTOMATIC' then
    return;
  end if;

  if v_game.status = 'COUNTDOWN' then
    if v_game.phase_started_at is null
      or now() < v_game.phase_started_at + make_interval(secs => countdown_seconds)
    then
      return;
    end if;

    select id into v_next_gq_id from game_questions
      where game_id = p_game_id and round_number = v_game.round_number and question_order = 0;

    if v_next_gq_id is null then
      raise exception 'No questions were prepared for this game.' using errcode = 'P0006';
    end if;

    update games
      set status = 'QUESTION',
          current_question_index = 0,
          current_question_id = v_next_gq_id,
          question_started_at = now()
      where id = p_game_id;
    return;
  end if;

  if v_game.status = 'QUESTION' then
    if v_game.question_started_at is null
      or now() < v_game.question_started_at + make_interval(secs => v_game.time_limit_seconds)
    then
      return;
    end if;

    select * into v_gq from game_questions where id = v_game.current_question_id;
    v_no_answer_points := (v_game.scoring_config->>'noAnswerPoints')::integer;

    insert into answers (game_id, round_number, player_id, question_id, selected_option, is_correct, response_time_ms, points)
    select p_game_id, v_game.round_number, p.id, v_gq.question_id, null, false, null, v_no_answer_points
    from players p
    where p.game_id = p_game_id
      and not exists (
        select 1 from answers a
        where a.game_id = p_game_id
          and a.round_number = v_game.round_number
          and a.player_id = p.id
          and a.question_id = v_gq.question_id
      );

    update games set status = 'REVEAL', phase_started_at = now() where id = p_game_id;
    return;
  end if;

  if v_game.status = 'REVEAL' then
    if v_game.phase_started_at is null
      or now() < v_game.phase_started_at + make_interval(secs => reveal_seconds)
    then
      return;
    end if;

    update games set status = 'LEADERBOARD', phase_started_at = now() where id = p_game_id;
    return;
  end if;

  if v_game.status = 'LEADERBOARD' then
    if v_game.phase_started_at is null
      or now() < v_game.phase_started_at + make_interval(secs => leaderboard_seconds)
    then
      return;
    end if;

    v_next_index := v_game.current_question_index + 1;

    if v_next_index < v_game.question_count then
      select id into v_next_gq_id from game_questions
        where game_id = p_game_id and round_number = v_game.round_number and question_order = v_next_index;

      if v_next_gq_id is null then
        raise exception 'No questions were prepared for this game.' using errcode = 'P0006';
      end if;

      update games
        set status = 'QUESTION',
            current_question_index = v_next_index,
            current_question_id = v_next_gq_id,
            question_started_at = now()
        where id = p_game_id;
    else
      update games
        set status = 'FINISHED',
            finished_at = now()
        where id = p_game_id;
    end if;
    return;
  end if;
end;
$$;

-- ---------------------------------------------------------------------
-- play_again — new. Host-only, only once FINISHED. Resets the SAME games
-- row (same id, same room_code) back to WAITING with a fresh
-- round_number and every player's score zeroed, WITHOUT touching the
-- players table at all — see this migration's header comment.
-- ---------------------------------------------------------------------

create or replace function play_again(p_game_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  perform enforce_rate_limit('play_again', 10, 30);

  select * into v_game from games where id = p_game_id for update;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  if v_game.host_user_id <> v_uid then
    raise exception 'Only the host can start a new round.' using errcode = '42501';
  end if;

  if v_game.status <> 'FINISHED' then
    raise exception 'This game hasn''t finished yet.' using errcode = 'P0001';
  end if;

  update games
    set status = 'WAITING',
        round_number = round_number + 1,
        current_question_index = 0,
        current_question_id = null,
        question_started_at = null,
        phase_started_at = null,
        started_at = null,
        finished_at = null
    where id = p_game_id;

  update players set score = 0 where game_id = p_game_id;
end;
$$;

revoke execute on function play_again(uuid) from public;
grant execute on function play_again(uuid) to authenticated;


-- ===================================================================
-- FROM: supabase/migrations/0017_faster_automatic_mode_timing.sql
-- ===================================================================
-- Pinoy Quiz — 0017: Automatic mode felt too slow — retune phase
-- durations
--
-- Reported directly: Automatic mode felt sluggish. The cause was the
-- fixed REVEAL_SECONDS/LEADERBOARD_SECONDS constants set in
-- 0015_automatic_mode_and_answer_behavior.sql — 6s + 5s = 11 seconds of
-- pure "waiting for the auto-advance timer" dead time on TOP of however
-- long the question itself takes, every single question. A 10-question
-- Automatic game was spending roughly two full minutes just sitting on
-- Reveal/Leaderboard screens with nothing left to do on them, before
-- counting the actual question time at all.
--
-- This migration only retunes those two constants — the mechanism itself
-- (auto_advance_game, phase_started_at, any-participant polling) is
-- unchanged and still fully explained in 0015's header comment:
--   REVEAL_SECONDS:      6 -> 3   (still enough to read a short
--                                  explanation and the correct answer;
--                                  the original 6s was sized generously
--                                  rather than tightly)
--   LEADERBOARD_SECONDS:  5 -> 2   (a rank/score change reads in about a
--                                  second; 5s was the biggest single
--                                  contributor to the sluggish feeling)
--   COUNTDOWN_SECONDS:    3 -> 3   (unchanged — this one is a cosmetic
--                                  "3, 2, 1, Go" the player is meant to
--                                  watch tick down, not dead time to
--                                  trim, and it has to keep matching
--                                  CountdownOverlay's default seconds
--                                  prop on the client)
--
-- src/hooks/useAutoAdvance.ts's poll interval also drops from 1000ms to
-- 500ms, so the extra lag between a phase's timer actually elapsing and
-- some client's next poll picking it up shrinks too — see that file for
-- why 500ms still stays comfortably under auto_advance_game's rate limit
-- (0015: 60 calls / 20s per user, i.e. an average of 3/s; 500ms is 2/s).
--
-- Net effect per question: ~11s of forced dead time drops to ~5s, plus
-- less than half as much poll lag on either side of it.

create or replace function auto_advance_game(p_game_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_game games%rowtype;
  v_gq game_questions%rowtype;
  v_no_answer_points integer;
  v_next_index smallint;
  v_next_gq_id uuid;
  countdown_seconds constant int := 3;   -- unchanged — matches CountdownOverlay
  reveal_seconds constant int := 3;      -- was 6
  leaderboard_seconds constant int := 2; -- was 5
begin
  if v_uid is null then
    raise exception 'You must be signed in.' using errcode = '28000';
  end if;

  perform enforce_rate_limit('auto_advance_game', 60, 20);

  select * into v_game from games where id = p_game_id for update;
  if not found then
    raise exception 'Game not found.' using errcode = 'P0002';
  end if;

  if not exists (select 1 from players where game_id = p_game_id and user_id = v_uid) then
    raise exception 'You are not part of this game.' using errcode = '42501';
  end if;

  if v_game.game_mode <> 'AUTOMATIC' then
    return;
  end if;

  if v_game.status = 'COUNTDOWN' then
    if v_game.phase_started_at is null
      or now() < v_game.phase_started_at + make_interval(secs => countdown_seconds)
    then
      return;
    end if;

    select id into v_next_gq_id from game_questions
      where game_id = p_game_id and round_number = v_game.round_number and question_order = 0;

    if v_next_gq_id is null then
      raise exception 'No questions were prepared for this game.' using errcode = 'P0006';
    end if;

    update games
      set status = 'QUESTION',
          current_question_index = 0,
          current_question_id = v_next_gq_id,
          question_started_at = now()
      where id = p_game_id;
    return;
  end if;

  if v_game.status = 'QUESTION' then
    if v_game.question_started_at is null
      or now() < v_game.question_started_at + make_interval(secs => v_game.time_limit_seconds)
    then
      return;
    end if;

    select * into v_gq from game_questions where id = v_game.current_question_id;
    v_no_answer_points := (v_game.scoring_config->>'noAnswerPoints')::integer;

    insert into answers (game_id, round_number, player_id, question_id, selected_option, is_correct, response_time_ms, points)
    select p_game_id, v_game.round_number, p.id, v_gq.question_id, null, false, null, v_no_answer_points
    from players p
    where p.game_id = p_game_id
      and not exists (
        select 1 from answers a
        where a.game_id = p_game_id
          and a.round_number = v_game.round_number
          and a.player_id = p.id
          and a.question_id = v_gq.question_id
      );

    update games set status = 'REVEAL', phase_started_at = now() where id = p_game_id;
    return;
  end if;

  if v_game.status = 'REVEAL' then
    if v_game.phase_started_at is null
      or now() < v_game.phase_started_at + make_interval(secs => reveal_seconds)
    then
      return;
    end if;

    update games set status = 'LEADERBOARD', phase_started_at = now() where id = p_game_id;
    return;
  end if;

  if v_game.status = 'LEADERBOARD' then
    if v_game.phase_started_at is null
      or now() < v_game.phase_started_at + make_interval(secs => leaderboard_seconds)
    then
      return;
    end if;

    v_next_index := v_game.current_question_index + 1;

    if v_next_index < v_game.question_count then
      select id into v_next_gq_id from game_questions
        where game_id = p_game_id and round_number = v_game.round_number and question_order = v_next_index;

      if v_next_gq_id is null then
        raise exception 'No questions were prepared for this game.' using errcode = 'P0006';
      end if;

      update games
        set status = 'QUESTION',
            current_question_index = v_next_index,
            current_question_id = v_next_gq_id,
            question_started_at = now()
        where id = p_game_id;
    else
      update games
        set status = 'FINISHED',
            finished_at = now()
        where id = p_game_id;
    end if;
    return;
  end if;
end;
$$;


-- ===================================================================
-- FROM: supabase/migrations/0018_expand_categories.sql
-- ===================================================================
-- Pinoy Quiz — 0018: expand question categories
--
-- Adds 15 new category values to both `game_category_setting` and
-- `question_category` (see 0002_enums.sql). Of the 20 categories requested
-- for this expansion, 5 already existed under a different (already-
-- Philippines-scoped) name and are intentionally NOT duplicated:
--   "Philippine History"          -> existing `history`
--   "Filipino Food & Cuisine"     -> existing `food`
--   "Filipino Sports"             -> existing `sports`
--   "Filipino Slang & Expressions"-> existing `slang`
--   "General Philippines Trivia"  -> existing `trivia`
-- New questions for those five were added to the existing enum values in
-- 0019 rather than creating redundant categories.
--
-- IMPORTANT — why this is its own migration file, doing nothing else:
-- Postgres does not allow a newly-added enum value to be referenced by the
-- same transaction that added it (`ALTER TYPE ... ADD VALUE` cannot run in
-- the same transaction as a later `INSERT`/`SELECT` using that value,
-- unless run outside a transaction block entirely on PG12+, which most
-- migration runners including Supabase's do not guarantee). Since Supabase
-- CLI applies each migration file as its own transaction, keeping the
-- enum-expansion isolated in this file — with the actual question INSERTs
-- deferred to 0019_new_categories_and_questions.sql — is what makes this
-- migration set safe to run end-to-end, unattended, in one pass.
--
-- Safe to re-run: `ADD VALUE IF NOT EXISTS` is a no-op if the value is
-- already present.

alter type game_category_setting add value if not exists 'politics_government';
alter type game_category_setting add value if not exists 'provinces_cities';
alter type game_category_setting add value if not exists 'languages';
alter type game_category_setting add value if not exists 'literature';
alter type game_category_setting add value if not exists 'music';
alter type game_category_setting add value if not exists 'movies_tv';
alter type game_category_setting add value if not exists 'celebrities';
alter type game_category_setting add value if not exists 'festivals';
alter type game_category_setting add value if not exists 'mythology_folklore';
alter type game_category_setting add value if not exists 'nature_wildlife';
alter type game_category_setting add value if not exists 'landmarks';
alter type game_category_setting add value if not exists 'innovations';
alter type game_category_setting add value if not exists 'economy_business';
alter type game_category_setting add value if not exists 'technology';
alter type game_category_setting add value if not exists 'religion_traditions';

alter type question_category add value if not exists 'politics_government';
alter type question_category add value if not exists 'provinces_cities';
alter type question_category add value if not exists 'languages';
alter type question_category add value if not exists 'literature';
alter type question_category add value if not exists 'music';
alter type question_category add value if not exists 'movies_tv';
alter type question_category add value if not exists 'celebrities';
alter type question_category add value if not exists 'festivals';
alter type question_category add value if not exists 'mythology_folklore';
alter type question_category add value if not exists 'nature_wildlife';
alter type question_category add value if not exists 'landmarks';
alter type question_category add value if not exists 'innovations';
alter type question_category add value if not exists 'economy_business';
alter type question_category add value if not exists 'technology';
alter type question_category add value if not exists 'religion_traditions';

-- No changes needed to create_game/start_game/lookup_game_by_room_code
-- (0014_security_hardening.sql): they all filter/accept by the enum TYPE,
-- not by an enumerated list of its values, so the new categories are
-- automatically selectable and playable the moment this migration lands.


-- ===================================================================
-- FROM: supabase/migrations/0019_new_categories_and_questions.sql
-- ===================================================================
-- Pinoy Quiz — 0019: new categories + 200 new questions (Phase 15 expansion)
--
-- Adds 200 new, English-language, Philippines-focused questions across the
-- 15 newly-added categories from 0018 (10 each = 150) plus a top-up of the
-- 8 original categories (50 more, varying per category) — see
-- CHANGELOG.md and docs/MASTER_HANDOFF.md for the full breakdown and
-- rationale. None of the 80 questions from
-- supabase/seed/0001_sample_questions.sql are modified, removed, or
-- duplicated here — this migration only adds new rows.
--
