insert into questions (category, difficulty, question_type, prompt, match_terms, match_definitions, source_question_ids, is_adapted)
values ('mathematics', 'easy', 'matching', 'Match each item to its correct description.', ARRAY['96','3.14']::text[], ARRAY['12 multiplied by 8','The value of pi (π), rounded to two decimal places']::text[], ARRAY['c599562e-a2aa-4e36-aa0d-b293f6ceaa6d','ce8a93f1-ac85-4746-ac67-cdd9264ea1c9']::uuid[], true);
